-- Version « une seule commande » de cles_examen.sql (générée).
-- Copiez TOUT le fichier et exécutez-le en une fois.
do $principal$
begin
  execute $c0$delete from public.cles_examen$c0$;
  execute $c1$delete from public.modules$c1$;
  execute $c2$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n1m1', 1, 1, 3)$c2$;
  execute $c3$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 0, 'La mort', '« Car le salaire du péché, c''est la mort ; mais le don gratuit de Dieu, c''est la vie éternelle » (Romains 6.23).')$c3$;
  execute $c4$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 1, 'Manquer la cible, s''écarter du but', 'Chatta''t évoque l''idée de manquer le but ; le même verbe est employé pour des frondeurs qui ne manquaient pas le but (Juges 20.16).')$c4$;
  execute $c5$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 2, 'Semer le doute sur la parole de Dieu : « Dieu a-t-il réellement dit ? »', 'Le serpent commence par mettre en doute la parole de Dieu, puis accuse Dieu de mentir (Genèse 3.1-5).')$c5$;
  execute $c6$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 3, 'Nathan', 'Dieu envoie Nathan, qui raconte la parabole de la petite brebis et dit à David : « Tu es cet homme-là ! » (2 Samuel 12.1-7).')$c6$;
  execute $c7$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 4, '« J''ai péché contre l''Éternel ! »', 'David reconnaît sa faute sans excuse : « J''ai péché contre l''Éternel ! » et Nathan lui annonce le pardon (2 Samuel 12.13).')$c7$;
  execute $c8$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 5, 'Nos crimes et nos péchés', '« Ce sont vos crimes qui mettent une séparation entre vous et votre Dieu » ; la main de l''Éternel n''est pas trop courte pour sauver (Ésaïe 59.1-2).')$c8$;
  execute $c9$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 6, 'Juifs et Grecs sont tous sous l''empire du péché', 'Paul conclut que « Juifs et Grecs, sont tous sous l''empire du péché » et que nul n''est juste (Romains 3.9-10).')$c9$;
  execute $c10$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 7, 'Faire connaître le péché', '« C''est par la loi que vient la connaissance du péché » : la Loi montre la maladie comme un miroir, elle ne la guérit pas (Romains 3.20).')$c10$;
  execute $c11$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 8, 'Par la grâce, par le moyen de la foi', '« C''est par la grâce que vous êtes sauvés, par le moyen de la foi… ce n''est point par les œuvres » (Éphésiens 2.8-9).')$c11$;
  execute $c12$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 9, 'Elles sont le fruit du salut : nous avons été créés en Christ pour les pratiquer', 'Nous sommes « créés en Jésus-Christ pour de bonnes œuvres, que Dieu a préparées d''avance » : sauvés non par les œuvres, mais pour les œuvres.')$c12$;
  execute $c13$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 10, '« Souviens-toi de moi, quand tu viendras dans ton règne »', 'Il dit : « Souviens-toi de moi, quand tu viendras dans ton règne », et Jésus lui promet : « aujourd''hui tu seras avec moi dans le paradis » (Luc 23.42-43).')$c13$;
  execute $c14$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 11, 'Que le salut est reçu par la foi, comme un don, sans mérite', 'Le brigand n''avait aucune œuvre à offrir ; il a cru et Jésus l''a sauvé le jour même (Luc 23.40-43).')$c14$;
  execute $c15$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 12, 'Changer de pensée et de direction : quitter le péché pour se tourner vers Dieu', 'Metanoia signifie un changement de pensée qui entraîne un changement de direction ; Jésus dit : « Repentez-vous, et croyez à la bonne nouvelle » (Marc 1.15).')$c15$;
  execute $c16$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 13, 'Le propitiatoire, lieu où le sang du sacrifice couvrait le péché', 'Hilastêrion désigne le propitiatoire de l''arche (Lévitique 16) ; Jésus est celui en qui la juste colère de Dieu contre le péché est apaisée.')$c16$;
  execute $c17$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 14, 'Faux', 'Faux : « Dieu prouve son amour envers nous, en ce que, lorsque nous étions encore des pécheurs, Christ est mort pour nous » (Romains 5.8).')$c17$;
  execute $c18$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 15, 'Pharisien, chef des Juifs et docteur d''Israël', 'Nicodème était pharisien, chef des Juifs, et Jésus l''appelle « le docteur d''Israël » (Jean 3.1, 10).')$c18$;
  execute $c19$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 16, 'Le serpent d''airain élevé par Moïse dans le désert', '« Comme Moïse éleva le serpent dans le désert, il faut de même que le Fils de l''homme soit élevé, afin que quiconque croit en lui ait la vie éternelle » (Jean 3.14-15 ; Nombres 21.4-9).')$c19$;
  execute $c20$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 17, 'Pour que les croyants sachent qu''ils ont la vie éternelle', '« Je vous ai écrit ces choses, afin que vous sachiez que vous avez la vie éternelle, vous qui croyez au nom du Fils de Dieu » (1 Jean 5.13).')$c20$;
  execute $c21$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 18, '« Ton assurance repose sur la promesse de Dieu : celui qui a le Fils a la vie »', 'L''assurance repose d''abord sur la Parole de Dieu, qui ne change pas : « Celui qui a le Fils a la vie » (1 Jean 5.12).')$c21$;
  execute $c22$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m1', 19, 'Confesser son péché, car Dieu est fidèle et juste pour le pardonner et le purifier', '« Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité » (1 Jean 1.9).')$c22$;
  execute $c23$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n1m2', 1, 2, 3)$c23$;
  execute $c24$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 0, 'Un seul Dieu en trois personnes : Père, Fils et Saint-Esprit', '« L''Éternel, notre Dieu, est le seul Éternel » (Deutéronome 6.4), et ce Dieu unique se révèle comme Père, Fils et Saint-Esprit (Matthieu 28.19).')$c24$;
  execute $c25$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 1, 'Comme un Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité', '« L''Éternel, l''Éternel, Dieu miséricordieux et compatissant, lent à la colère, riche en bonté et en fidélité » (Exode 34.6).')$c25$;
  execute $c26$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 2, 'L''amour fidèle et loyal de l''alliance', 'Chesed désigne l''amour loyal de l''alliance, un amour qui ne lâche pas l''autre (Exode 34.6 ; Psaume 103.8).')$c26$;
  execute $c27$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 3, 'Comme un père a compassion de ses enfants', '« Comme un père a compassion de ses enfants, l''Éternel a compassion de ceux qui le craignent » (Psaume 103.13).')$c27$;
  execute $c28$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 4, 'Il est ému de compassion, il court se jeter à son cou et le baise', '« Comme il était encore loin, son père le vit et fut ému de compassion, il courut se jeter à son cou et le baisa » (Luc 15.20).')$c28$;
  execute $c29$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 5, 'Aux pharisiens et aux scribes qui murmuraient parce qu''il accueillait les pécheurs', 'Les pharisiens murmuraient : « Cet homme accueille des gens de mauvaise vie, et il mange avec eux » ; le fils aîné de la parabole les représente (Luc 15.1-2, 25-32).')$c29$;
  execute $c30$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 6, 'Père, avec une nuance d''intimité familiale', 'Abba est le mot de l''intimité familiale pour « Père » (Marc 14.36) ; l''Esprit nous fait crier « Abba ! Père ! » (Romains 8.15).')$c30$;
  execute $c31$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 7, 'La Parole éternelle, qui était Dieu, faite chair', '« La Parole était Dieu… Et la parole a été faite chair, et elle a habité parmi nous » (Jean 1.1, 14).')$c31$;
  execute $c32$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 8, 'Dresser sa tente', 'Skênoô signifie « dresser sa tente » et rappelle le tabernacle où habitait la gloire de Dieu : en Jésus, Dieu est venu habiter parmi nous.')$c32$;
  execute $c33$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 9, '« Quel est donc celui-ci, à qui obéissent même le vent et la mer ? »', 'Ils furent saisis d''une grande frayeur et se dirent : « Quel est donc celui-ci, à qui obéissent même le vent et la mer ? » (Marc 4.41).')$c33$;
  execute $c34$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 10, '« Mon Seigneur et mon Dieu ! »', 'Thomas confesse : « Mon Seigneur et mon Dieu ! » (Jean 20.28), et Jésus accepte cette adoration.')$c34$;
  execute $c35$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 11, 'En se dépouillant, prenant une forme de serviteur et obéissant jusqu''à la mort de la croix', 'Existant en forme de Dieu, il s''est dépouillé, a pris une forme de serviteur, et s''est rendu obéissant jusqu''à la mort de la croix (Philippiens 2.6-8).')$c35$;
  execute $c36$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 12, 'Seul Dieu peut sauver, et il fallait un homme pour mourir à la place des hommes', 'Seul Dieu peut sauver (Ésaïe 43.11), et c''est un homme qui devait réparer ce qu''Adam avait détruit et mourir à notre place (Romains 5.19 ; Hébreux 2.17).')$c36$;
  execute $c37$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 13, 'Il est toujours vivant pour intercéder en faveur de ceux qui s''approchent de Dieu par lui', '« Il peut sauver parfaitement ceux qui s''approchent de Dieu par lui, étant toujours vivant pour intercéder en leur faveur » (Hébreux 7.25).')$c37$;
  execute $c38$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 14, 'Faux', 'Faux : « Si tu confesses de ta bouche le Seigneur Jésus… tu seras sauvé » (Romains 10.9). Jésus est à la fois Sauveur et Seigneur.')$c38$;
  execute $c39$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 15, 'Une personne divine qui parle, enseigne et peut être attristée', 'L''Esprit parle (Actes 13.2), enseigne (Jean 14.26), peut être attristé (Éphésiens 4.30) et mentir au Saint-Esprit, c''est mentir à Dieu (Actes 5.3-4).')$c39$;
  execute $c40$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 16, 'Celui qui est appelé à côté : avocat, défenseur, aide', 'Paraklêtos signifie « appelé à côté » : l''Esprit vient à nos côtés comme avocat, défenseur et aide (Jean 14.16-17).')$c40$;
  execute $c41$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 17, 'Du péché, de la justice et du jugement', '« Il convaincra le monde en ce qui concerne le péché, la justice, et le jugement » (Jean 16.8).')$c41$;
  execute $c42$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 18, 'La prophétie de Joël : « Je répandrai de mon Esprit sur toute chair »', 'Pierre cite Joël 2.28-32 : « Dans les derniers jours, dit Dieu, je répandrai de mon Esprit sur toute chair » (Actes 2.16-17).')$c42$;
  execute $c43$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m2', 19, 'L''Esprit glorifie Jésus, ne contredit pas l''Écriture, et le don de Dieu ne s''achète pas', 'L''Esprit glorifie Christ (Jean 16.14) ; il faut tout éprouver (1 Thessaloniciens 5.21), et Pierre condamne Simon qui pensait acquérir le don de Dieu à prix d''argent (Actes 8.20).')$c43$;
  execute $c44$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n1m3', 1, 3, 3)$c44$;
  execute $c45$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 0, '66', 'La Bible protestante compte 66 livres : 39 dans l''Ancien Testament et 27 dans le Nouveau Testament.')$c45$;
  execute $c46$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 1, 'Soufflée par Dieu', 'Theopneustos vient de theos (Dieu) et pneô (souffler) : l''Écriture est « soufflée par Dieu » (2 Timothée 3.16).')$c46$;
  execute $c47$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 2, 'Enseigner, convaincre, corriger, instruire dans la justice', '« Toute Écriture est inspirée de Dieu, et utile pour enseigner, pour convaincre, pour corriger, pour instruire dans la justice » (2 Timothée 3.16).')$c47$;
  execute $c48$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 3, 'Poussés par le Saint-Esprit, de la part de Dieu', '« Ce n''est pas par une volonté d''homme qu''une prophétie a jamais été apportée, mais c''est poussés par le Saint-Esprit que des hommes ont parlé de la part de Dieu » (2 Pierre 1.21).')$c48$;
  execute $c49$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 4, 'Josias', 'Le grand prêtre Hilkija trouva le livre de la loi pendant les réparations du temple, la dix-huitième année du roi Josias (2 Rois 22.3-8).')$c49$;
  execute $c50$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 5, 'Il déchira ses vêtements et s''humilia devant l''Éternel', '« Lorsque le roi entendit les paroles du livre de la loi, il déchira ses vêtements » (2 Rois 22.11) ; Dieu vit qu''il s''était humilié (22.19).')$c50$;
  execute $c51$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 6, 'Il le découpa et le jeta au feu', 'Jojakim coupa les colonnes du rouleau et les jeta au feu ; mais Dieu fit écrire un autre rouleau avec les mêmes paroles (Jérémie 36.23, 28).')$c51$;
  execute $c52$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 7, 'Vivante et efficace, plus tranchante qu''une épée à deux tranchants', '« La parole de Dieu est vivante et efficace, plus tranchante qu''une épée quelconque à deux tranchants… elle juge les sentiments et les pensées du cœur » (Hébreux 4.12).')$c52$;
  execute $c53$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 8, 'Trois : l''hébreu, l''araméen et le grec', 'L''Ancien Testament a été écrit surtout en hébreu, avec quelques passages en araméen, et le Nouveau Testament en grec.')$c53$;
  execute $c54$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 9, 'Le chapitre', '« Jean 3.16 » signifie : livre de Jean, chapitre 3, verset 16.')$c54$;
  execute $c55$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 10, '27', 'Le Nouveau Testament compte 27 livres : 4 Évangiles, les Actes, 13 lettres de Paul, 8 autres lettres et l''Apocalypse.')$c55$;
  execute $c56$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 11, 'Genèse, Exode, Lévitique, Nombres, Deutéronome', 'Le Pentateuque, ou livres de Moïse, comprend la Genèse, l''Exode, le Lévitique, les Nombres et le Deutéronome.')$c56$;
  execute $c57$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 12, 'Commençant par Moïse et tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait', '« Commençant par Moïse et par tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait » (Luc 24.27).')$c57$;
  execute $c58$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 13, 'Faux', 'Faux : Jésus dit des Écritures « ce sont elles qui rendent témoignage de moi » (Jean 5.39) ; l''Ancien Testament l''annonce, le Nouveau le révèle.')$c58$;
  execute $c59$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 14, 'Une lampe à mes pieds et une lumière sur mon sentier', '« Ta parole est une lampe à mes pieds, et une lumière sur mon sentier » (Psaume 119.105).')$c59$;
  execute $c60$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 15, 'Murmurer, répéter, ruminer la Parole', 'Hagah signifie murmurer, prononcer à mi-voix, ruminer : méditer, c''est garder la Parole en bouche et dans le cœur pour agir fidèlement (Josué 1.8).')$c60$;
  execute $c61$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 16, 'Étudier, mettre en pratique, puis enseigner', 'Esdras « avait appliqué son cœur à étudier et à mettre en pratique la loi de l''Éternel, et à enseigner au milieu d''Israël » (Esdras 7.10).')$c61$;
  execute $c62$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 17, 'Ils en donnaient le sens pour faire comprendre ce qu''on avait lu', '« Ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens pour faire comprendre ce qu''ils avaient lu » (Néhémie 8.8).')$c62$;
  execute $c63$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 18, 'À un homme qui se regarde dans un miroir et oublie aussitôt son visage', 'Il est « semblable à un homme qui regarde dans un miroir son visage naturel, et qui, après s''être regardé, s''en va, et oublie aussitôt quel il était » (Jacques 1.23-24).')$c63$;
  execute $c64$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m3', 19, 'Vérifier le verset cité dans la Bible et lire tout le passage autour, comme les Béréens', 'Les Béréens « examinaient chaque jour les Écritures, pour voir si ce qu''on leur disait était exact » (Actes 17.11) ; il faut lire chaque verset dans son contexte.')$c64$;
  execute $c65$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n1m4', 1, 4, 3)$c65$;
  execute $c66$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 0, 'De prier pour être vus des hommes', 'Ils prient pour être vus des hommes et ont déjà reçu leur récompense ; Jésus invite à prier le Père dans le secret (Matthieu 6.5-6).')$c66$;
  execute $c67$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 1, 'Parce que le Père sait de quoi nous avons besoin avant que nous le lui demandions', 'Les païens pensaient être exaucés à force de paroles ; mais « votre Père sait de quoi vous avez besoin, avant que vous le lui demandiez » (Matthieu 6.8).')$c67$;
  execute $c68$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 2, 'Des demandes tournées vers Dieu : son nom, son règne, sa volonté', 'Le modèle de Jésus commence par Dieu : que ton nom soit sanctifié, que ton règne vienne, que ta volonté soit faite (Matthieu 6.9-10).')$c68$;
  execute $c69$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 3, 'Dettes', 'Le mot opheilêmata signifie « dettes » : le péché est une dette envers Dieu, que lui seul peut remettre (Matthieu 6.12).')$c69$;
  execute $c70$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 4, 'Les faire connaître à Dieu par la prière, avec des actions de grâces', 'Paul invite à faire connaître nos besoins à Dieu par des prières et des supplications, avec des actions de grâces ; la paix de Dieu gardera alors nos cœurs (Philippiens 4.6-7).')$c70$;
  execute $c71$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 5, 'Ses lèvres remuent mais on n''entend pas sa voix', 'Anne parlait dans son cœur ; seules ses lèvres remuaient. Elle explique : « je répandais mon âme devant l''Éternel » (1 Samuel 1.13-15).')$c71$;
  execute $c72$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 6, 'Je l''ai demandé à l''Éternel', 'Anne l''appela Samuel, « car, dit-elle, je l''ai demandé à l''Éternel » (1 Samuel 1.20).')$c72$;
  execute $c73$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 7, 'Vrai', 'Après la bénédiction d''Éli, Anne s''en alla, mangea, et son visage ne fut plus le même (1 Samuel 1.18) : la paix précède la réponse.')$c73$;
  execute $c74$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 8, 'Un temps où la parole de l''Éternel était rare', '« La parole de l''Éternel était rare en ce temps-là, les visions n''étaient pas fréquentes » (1 Samuel 3.1).')$c74$;
  execute $c75$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 9, 'Répondre : Parle, Éternel, car ton serviteur écoute', 'Éli lui dit : « si l''on t''appelle, tu diras : Parle, Éternel, car ton serviteur écoute » (1 Samuel 3.9).')$c75$;
  execute $c76$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 10, 'Obéir', 'Écouter Dieu, dans la Bible, c''est entendre et mettre en pratique ; c''est le mot de « Écoute, Israël ! » (Deutéronome 6.4).')$c76$;
  execute $c77$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 11, 'Elles entendent sa voix et le suivent', '« Mes brebis entendent ma voix ; je les connais, et elles me suivent » (Jean 10.27).')$c77$;
  execute $c78$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 12, 'Sa Parole écrite, la Bible', '« Toute Écriture est inspirée de Dieu, et utile pour enseigner… » (2 Timothée 3.16) ; tout autre moyen doit être vérifié par elle.')$c78$;
  execute $c79$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 13, 'Examiner cette parole à la lumière de l''Écriture et demander conseil à des croyants mûrs', '« Examinez toutes choses ; retenez ce qui est bon » (1 Thessaloniciens 5.21) ; le bon berger ne vend pas sa voix.')$c79$;
  execute $c80$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 14, 'Cesser de s''agiter, lâcher prise et reconnaître qui est Dieu', 'Le verbe râphâh signifie relâcher, cesser ; au milieu des bouleversements, Dieu invite à reconnaître sa souveraineté (Psaume 46.11).')$c80$;
  execute $c81$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 15, 'Pour montrer qu''il faut toujours prier, et ne point se relâcher', 'Luc l''annonce dès le premier verset : « pour montrer qu''il faut toujours prier, et ne point se relâcher » (Luc 18.1).')$c81$;
  execute $c82$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 16, 'Faux', 'Jésus raisonne par contraste : si un juge injuste finit par faire justice, combien plus Dieu fera-t-il justice à ses élus (Luc 18.6-8).')$c82$;
  execute $c83$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 17, 'Trois semaines', 'Daniel mena le deuil trois semaines entières ; le messager explique que le chef du royaume de Perse lui a résisté vingt et un jours (Daniel 10.2-3, 13).')$c83$;
  execute $c84$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 18, 'En gardant une apparence normale, pour le Père qui voit dans le secret', '« Parfume ta tête et lave ton visage, afin de ne pas montrer aux hommes que tu jeûnes, mais à ton Père qui est là dans le lieu secret » (Matthieu 6.17-18).')$c84$;
  execute $c85$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m4', 19, 'Un jeûne qui libère les opprimés et partage le pain avec celui qui a faim', 'Dieu dit : « Voici le jeûne auquel je prends plaisir : Détache les chaînes de la méchanceté… Partage ton pain avec celui qui a faim » (Ésaïe 58.6-7).')$c85$;
  execute $c86$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n1m5', 1, 5, 3)$c86$;
  execute $c87$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 0, 'L''enseignement des apôtres, la communion fraternelle, la fraction du pain et les prières', '« Ils persévéraient dans l''enseignement des apôtres, dans la communion fraternelle, dans la fraction du pain, et dans les prières » (Actes 2.42).')$c87$;
  execute $c88$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 1, 'Une assemblée de personnes convoquées', 'L''ekklêsia est l''assemblée de ceux que Dieu a appelés en Christ ; l''Église n''est pas un bâtiment mais un peuple (1 Pierre 2.9).')$c88$;
  execute $c89$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 2, 'Trois mille', '« Ceux qui acceptèrent sa parole furent baptisés ; et, en ce jour-là, furent ajoutées environ trois mille âmes » (Actes 2.41).')$c89$;
  execute $c90$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 3, 'Il n''en est pas moins du corps', 'Paul demande : « ne serait-il pas du corps pour cela ? » (1 Corinthiens 12.15) : chaque membre est nécessaire, même s''il n''a pas le don des autres.')$c90$;
  execute $c91$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 4, 'Tous les membres souffrent avec lui', '« Si un membre souffre, tous les membres souffrent avec lui ; si un membre est honoré, tous les membres se réjouissent avec lui » (1 Corinthiens 12.26).')$c91$;
  execute $c92$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 5, 'De ne pas l''abandonner, comme c''est la coutume de quelques-uns', '« N''abandonnons pas notre assemblée, comme c''est la coutume de quelques-uns ; mais exhortons-nous réciproquement » (Hébreux 10.25).')$c92$;
  execute $c93$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 6, 'Faux', 'Le croyant est membre d''un corps (1 Corinthiens 12.27) et appelé à ne pas abandonner l''assemblée (Hébreux 10.25) ; l''isolement volontaire l''affaiblit.')$c93$;
  execute $c94$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 7, 'Faites des disciples', 'En grec, le verbe principal est « faites des disciples » (mathêteuô), accompagné de « allez », « baptisant » et « enseignant ».')$c94$;
  execute $c95$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 8, 'Plonger, immerger', 'Baptizô signifie plonger, immerger ; Paul y voit l''image de l''ensevelissement et de la résurrection avec Christ (Romains 6.4).')$c95$;
  execute $c96$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 9, 'Notre union avec Christ dans sa mort et sa résurrection pour une vie nouvelle', '« Nous avons donc été ensevelis avec lui par le baptême en sa mort, afin que… nous aussi nous marchions en nouveauté de vie » (Romains 6.4).')$c96$;
  execute $c97$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 10, 'Ésaïe 53', 'Il lisait : « Il a été mené comme une brebis à la boucherie… » (Ésaïe 53.7-8, cité en Actes 8.32-33), et Philippe lui annonça Jésus à partir de ce passage.')$c97$;
  execute $c98$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 11, '« Qu''est-ce qui empêche que je sois baptisé ? »', '« Voici de l''eau ; qu''est-ce qui empêche que je sois baptisé ? » (Actes 8.36) : le baptême suit de près la foi en Jésus.')$c98$;
  execute $c99$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 12, 'Nous sommes sauvés par grâce par la foi, et le baptême est l''obéissance et le témoignage public de cette foi', 'Le salut est par grâce, par la foi (Éphésiens 2.8-9) ; le baptême, commandé par Jésus (Matthieu 28.19), est « l''engagement d''une bonne conscience envers Dieu » (1 Pierre 3.21).')$c99$;
  execute $c100$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 13, 'Faux', 'La majorité pratique le baptême des croyants, mais d''autres évangéliques (réformés, presbytériens, anglicans) baptisent aussi les enfants de croyants ; on en parle avec respect.')$c100$;
  execute $c101$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 14, 'La Pâque', 'Jésus dit : « J''ai désiré vivement manger cette Pâque avec vous, avant de souffrir » (Luc 22.15) ; « Christ, notre Pâque, a été immolé » (1 Corinthiens 5.7).')$c101$;
  execute $c102$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 15, 'Le sang de l''agneau sur les portes', '« Le sang vous servira de signe sur les maisons où vous serez ; je verrai le sang, et je passerai par-dessus vous » (Exode 12.13).')$c102$;
  execute $c103$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 16, 'La nouvelle alliance dans le sang de Jésus, répandu pour nous', '« Cette coupe est la nouvelle alliance en mon sang, qui est répandu pour vous » (Luc 22.20), selon la promesse de Jérémie 31.31-34.')$c103$;
  execute $c104$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 17, 'Nous annonçons la mort du Seigneur jusqu''à ce qu''il vienne', '« Toutes les fois que vous mangez ce pain et que vous buvez cette coupe, vous annoncez la mort du Seigneur, jusqu''à ce qu''il vienne » (1 Corinthiens 11.26).')$c104$;
  execute $c105$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 18, 'Les riches mangeaient sans attendre les pauvres, et certains s''enivraient', '« L''un a faim, tandis que l''autre est ivre… faites-vous honte à ceux qui n''ont rien ? » (1 Corinthiens 11.21-22) : le mépris des frères rendait le repas indigne.')$c105$;
  execute $c106$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m5', 19, 'S''éprouver soi-même et chercher d''abord à se réconcilier', 'Jésus dit : « va d''abord te réconcilier avec ton frère » (Matthieu 5.24), et Paul : « Que chacun donc s''éprouve soi-même » (1 Corinthiens 11.28).')$c106$;
  execute $c107$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n1m6', 1, 6, 3)$c107$;
  execute $c108$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 0, 'Faux', 'Jésus « a été tenté comme nous en toutes choses, sans commettre de péché » (Hébreux 4.15) ; le péché commence quand la convoitise est accueillie et « conçoit » (Jacques 1.15).')$c108$;
  execute $c109$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 1, 'De notre propre convoitise, qui nous attire et nous amorce', '« Dieu… ne tente lui-même personne. Mais chacun est tenté quand il est attiré et amorcé par sa propre convoitise » (Jacques 1.13-14).')$c109$;
  execute $c110$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 2, 'La convoitise conçoit et enfante le péché ; le péché consommé produit la mort', '« La convoitise, lorsqu''elle a conçu, enfante le péché ; et le péché, étant consommé, produit la mort » (Jacques 1.15).')$c110$;
  execute $c111$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 3, 'Que Dieu, fidèle, ne permettra pas de tentation au-delà de ses forces et préparera le moyen d''en sortir', '« Dieu, qui est fidèle, ne permettra pas que vous soyez tentés au delà de vos forces ; mais avec la tentation il préparera aussi le moyen d''en sortir » (1 Corinthiens 10.13).')$c111$;
  execute $c112$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 4, 'Des citations de l''Écriture : « Il est écrit »', 'Jésus a répondu trois fois par le Deutéronome : « Il est écrit » (Matthieu 4.4, 7, 10).')$c112$;
  execute $c113$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 5, 'Changer des pierres en pains', '« Si tu es Fils de Dieu, ordonne que ces pierres deviennent des pains » ; Jésus répond : « L''homme ne vivra pas de pain seulement » (Matthieu 4.3-4).')$c113$;
  execute $c114$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 6, 'Il cite lui-même un psaume en le détournant de son sens', 'Le diable cite le Psaume 91.11-12 pour pousser Jésus à se jeter du haut du temple ; Jésus répond : « Tu ne tenteras point le Seigneur, ton Dieu » (Matthieu 4.6-7).')$c114$;
  execute $c115$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 7, 'La convoitise de la chair, la convoitise des yeux et l''orgueil de la vie', '« Tout ce qui est dans le monde, la convoitise de la chair, la convoitise des yeux, et l''orgueil de la vie, ne vient point du Père » (1 Jean 2.16).')$c115$;
  execute $c116$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 8, 'Ce serait pécher contre Dieu', '« Comment ferais-je un aussi grand mal et pécherais-je contre Dieu ? » (Genèse 39.9).')$c116$;
  execute $c117$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 9, 'Il lui laisse son vêtement et s''enfuit dehors', '« Il lui laissa son vêtement dans la main, et s''enfuit au dehors » (Genèse 39.12) : certaines tentations ne se combattent pas, elles se fuient.')$c117$;
  execute $c118$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 10, 'En marchant selon l''Esprit', '« Marchez selon l''Esprit, et vous n''accomplirez pas les désirs de la chair » (Galates 5.16).')$c118$;
  execute $c119$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 11, 'La tempérance (maîtrise de soi)', 'Le fruit de l''Esprit est « l''amour, la joie, la paix, la patience, la bonté, la bénignité, la fidélité, la douceur, la tempérance » (Galates 5.22-23).')$c119$;
  execute $c120$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 12, 'Afin de ne pas pécher contre Dieu', '« Je serre ta parole dans mon cœur, afin de ne pas pécher contre toi » (Psaume 119.11).')$c120$;
  execute $c121$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 13, 'Les fuir, et rechercher la justice avec ceux qui invoquent le Seigneur d''un cœur pur', '« Fuis les passions de la jeunesse, et recherche la justice, la foi, la charité, la paix, avec ceux qui invoquent le Seigneur d''un cœur pur » (2 Timothée 2.22).')$c121$;
  execute $c122$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 14, 'Se soumettre à Dieu, puis résister au diable', '« Soumettez-vous donc à Dieu ; résistez au diable, et il fuira loin de vous » (Jacques 4.7).')$c122$;
  execute $c123$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 15, 'Il est fidèle et juste pour nous pardonner et nous purifier de toute iniquité', '« Si nous confessons nos péchés, il est fidèle et juste pour nous les pardonner, et pour nous purifier de toute iniquité » (1 Jean 1.9).')$c123$;
  execute $c124$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 16, 'Jésus-Christ le juste', '« Si quelqu''un a péché, nous avons un avocat auprès du Père, Jésus-Christ le juste » (1 Jean 2.1).')$c124$;
  execute $c125$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 17, 'Pierre est revenu vers Jésus et les disciples au lieu de s''enfermer dans le désespoir', 'Pierre pleura amèrement mais resta avec les disciples et fut restauré (Luc 22.62 ; Jean 21.15-17) ; Judas, rempli de remords, s''isola et se donna la mort (Matthieu 27.3-5).')$c125$;
  execute $c126$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 18, 'Trois fois', 'Trois fois, comme les trois reniements ; à chaque réponse, Jésus confie à Pierre la mission de paître ses brebis (Jean 21.15-17).')$c126$;
  execute $c127$insert into public.cles_examen (module_id, question, reponse, explication) values ('n1m6', 19, 'La conviction vient de l''Esprit et conduit à la repentance et à la restauration ; la condamnation écrase et éloigne de Dieu', '« La tristesse selon Dieu produit une repentance à salut… tandis que la tristesse du monde produit la mort » (2 Corinthiens 7.10) ; « il n''y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ » (Romains 8.1).')$c127$;
  execute $c128$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n2m1', 2, 7, 3)$c128$;
  execute $c129$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 0, 'À son image', '« Dieu créa l''homme à son image… il créa l''homme et la femme » (Genèse 1.27).')$c129$;
  execute $c130$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 1, 'Une représentation, un reflet, une statue', 'Tselem désigne une représentation : l''homme représente Dieu sur la terre et reflète quelque chose de lui.')$c130$;
  execute $c131$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 2, 'Gouverner, cultiver et garder la création au nom de Dieu', 'Dieu demande à l''homme de dominer sur la terre et place Adam dans le jardin « pour le cultiver et pour le garder » (Genèse 2.15).')$c131$;
  execute $c132$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 3, 'Parce qu''il est une créature si merveilleuse, œuvre admirable de Dieu', '« Je te loue de ce que je suis une créature si merveilleuse. Tes œuvres sont admirables » (Psaume 139.14).')$c132$;
  execute $c133$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 4, 'Dans le pressoir, où il battait le blé en cachette', 'Gédéon battait le froment au pressoir pour le soustraire aux Madianites (Juges 6.11-12).')$c133$;
  execute $c134$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 5, 'Sur sa présence : « Je serai avec toi »', 'L''Éternel lui dit : « Je serai avec toi, et tu battras Madian comme un seul homme » (Juges 6.16).')$c134$;
  execute $c135$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 6, 'Il est l''image du Dieu invisible', '« Il est l''image du Dieu invisible, le premier-né de toute la création » (Colossiens 1.15) ; en lui, l''image de Dieu est restaurée en nous.')$c135$;
  execute $c136$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 7, 'Faux', 'Faux : le péché a abîmé l''image de Dieu, mais Genèse 9.6 et Jacques 3.9 affirment que l''homme la porte encore.')$c136$;
  execute $c137$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 8, 'L''adoption, le placement comme fils', 'Huiothesia désigne l''adoption : un nouveau nom, une nouvelle famille et les pleins droits d''héritier.')$c137$;
  execute $c138$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 9, 'La rédemption par son sang, la rémission des péchés', '« En lui nous avons la rédemption par son sang, la rémission des péchés, selon la richesse de sa grâce » (Éphésiens 1.7).')$c138$;
  execute $c139$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 10, 'Le sceau et le gage de notre héritage', 'Les croyants ont été « scellés du Saint-Esprit qui avait été promis, lequel est un gage de notre héritage ».')$c139$;
  execute $c140$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 11, '« Abba ! Père ! »', '« Dieu a envoyé dans nos cœurs l''Esprit de son Fils, lequel crie : Abba ! Père ! » (Galates 4.6).')$c140$;
  execute $c141$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 12, 'Être traité comme l''un des ouvriers de son père', 'Il avait préparé de dire : « Traite-moi comme l''un de tes mercenaires » (Luc 15.19), mais le père le restaure comme fils.')$c141$;
  execute $c142$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 13, 'Que le fils est pleinement rétabli dans sa dignité de fils', 'Ces gestes honorent le fils, lui rendent l''autorité familiale et le distinguent des esclaves, qui marchaient pieds nus.')$c142$;
  execute $c143$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 14, 'Une mentalité d''ouvrier qui réclame son salaire', 'L''aîné pense en termes de mérite ; le père lui rappelle : « Tout ce que j''ai est à toi » (Luc 15.31).')$c143$;
  execute $c144$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 15, 'Une nouvelle créature', '« Si quelqu''un est en Christ, il est une nouvelle créature. Les choses anciennes sont passées » (2 Corinthiens 5.17).')$c144$;
  execute $c145$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 16, 'Elle tend un piège', '« La crainte des hommes tend un piège, mais celui qui se confie en l''Éternel est protégé » (Proverbes 29.25).')$c145$;
  execute $c146$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 17, 'Il craignait le peuple et avait écouté sa voix', 'Saül avoue : « Je craignais le peuple, et j''ai écouté sa voix » (1 Samuel 15.24).')$c146$;
  execute $c147$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 18, 'Il ne serait pas serviteur de Christ', '« Si je plaisais encore aux hommes, je ne serais pas serviteur de Christ » (Galates 1.10).')$c147$;
  execute $c148$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m1', 19, 'Faux', 'Faux : « Il n''y a donc maintenant aucune condamnation pour ceux qui sont en Jésus-Christ » (Romains 8.1).')$c148$;
  execute $c149$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n2m2', 2, 8, 3)$c149$;
  execute $c150$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 0, 'Pour être les témoins de Jésus', '« Vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins » (Actes 1.8).')$c150$;
  execute $c151$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 1, 'Jérusalem, la Judée, la Samarie et les extrémités de la terre', 'Ce programme sert de plan à tout le livre des Actes, de Jérusalem jusqu''à Rome.')$c151$;
  execute $c152$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 2, 'Ils persévéraient ensemble dans la prière', '« Tous d''un commun accord persévéraient dans la prière » dans la chambre haute (Actes 1.14).')$c152$;
  execute $c153$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 3, 'Un bruit comme celui d''un vent impétueux et des langues semblables à des langues de feu', 'Un bruit « comme celui d''un vent impétueux » remplit la maison, et des langues de feu se posèrent sur chacun d''eux.')$c153$;
  execute $c154$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 4, 'Repentez-vous, soyez baptisés au nom de Jésus-Christ, et vous recevrez le don du Saint-Esprit', 'Pierre appelle à la repentance et au baptême, avec la promesse du don du Saint-Esprit (Actes 2.38).')$c154$;
  execute $c155$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 5, 'Celui qui atteste ce qu''il a vu et entendu', 'Le témoin atteste ce qu''il a vu et entendu ; le mot a donné « martyr » en français.')$c155$;
  execute $c156$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 6, 'À l''ivresse du vin', '« Ne vous enivrez pas de vin : c''est de la débauche. Soyez, au contraire, remplis de l''Esprit » (Éphésiens 5.18).')$c156$;
  execute $c157$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 7, 'C''est un commandement pour tous, à recevoir de Dieu de façon continue', 'Impératif, pluriel, passif et présent : un appel adressé à tous à se laisser continuellement remplir par l''Esprit.')$c157$;
  execute $c158$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 8, 'Faux', 'Faux : « Si quelqu''un n''a pas l''Esprit de Christ, il ne lui appartient pas » (Romains 8.9).')$c158$;
  execute $c159$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 9, 'La renommée', 'La liste est : amour, joie, paix, patience, bonté, bénignité, fidélité, douceur, tempérance (Galates 5.22-23).')$c159$;
  execute $c160$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 10, 'Parce qu''il s''agit d''un seul caractère aux multiples aspects, celui de Christ', 'Le fruit est un caractère unifié, opposé aux « œuvres » multiples et désordonnées de la chair.')$c160$;
  execute $c161$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 11, 'Demeurer en Christ, le cep', '« Celui qui demeure en moi et en qui je demeure porte beaucoup de fruit, car sans moi vous ne pouvez rien faire » (Jean 15.5).')$c161$;
  execute $c162$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 12, 'Afin qu''ils portent encore plus de fruit', 'Le Vigneron émonde le sarment qui porte du fruit « afin qu''il porte encore plus de fruit » (Jean 15.2).')$c162$;
  execute $c163$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 13, 'Il a seulement coupé le pan de son manteau et a refusé de porter la main sur lui', 'David coupa le pan du manteau de Saül, mais refusa de porter la main sur « l''oint de l''Éternel » (1 Samuel 24.5-7).')$c163$;
  execute $c164$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 14, 'Une force maîtrisée et soumise à Dieu', 'Praütès évoque une force maîtrisée, comme celle d''un animal puissant mais dompté ; Jésus est « doux et humble de cœur ».')$c164$;
  execute $c165$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 15, 'Pour l''utilité commune', '« À chacun la manifestation de l''Esprit est donnée pour l''utilité commune » (1 Corinthiens 12.7).')$c165$;
  execute $c166$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 16, 'L''Esprit, qui les distribue à chacun comme il veut', '« Un seul et même Esprit opère toutes ces choses, les distribuant à chacun en particulier comme il veut. »')$c166$;
  execute $c167$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 17, 'De l''Esprit de Dieu, de sagesse, d''intelligence et de savoir pour toutes sortes d''ouvrages', 'Betsaleel fut rempli de l''Esprit de Dieu pour réaliser les ouvrages du tabernacle (Exode 31.3).')$c167$;
  execute $c168$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 18, 'Le mettre au service des autres comme un bon dispensateur', '« Que chacun de vous mette au service des autres le don qu''il a reçu », comme de bons dispensateurs de la grâce de Dieu.')$c168$;
  execute $c169$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m2', 19, 'Vrai', 'Vrai : sans la charité, celui qui parle les langues des hommes et des anges n''est qu''« un airain qui résonne ».')$c169$;
  execute $c170$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n2m3', 2, 9, 3)$c170$;
  execute $c171$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 0, 'Que l''homme soit seul', '« Il n''est pas bon que l''homme soit seul ; je lui ferai une aide semblable à lui » (Genèse 2.18).')$c171$;
  execute $c172$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 1, 'Un secours, mot souvent employé pour Dieu lui-même', 'ʿÉzer désigne un secours ; la Bible l''emploie souvent pour Dieu, « notre aide », sans aucune idée d''infériorité.')$c172$;
  execute $c173$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 2, 'Quitter, s''attacher, devenir une seule chair', '« L''homme quittera son père et sa mère, et s''attachera à sa femme, et ils deviendront une seule chair » (Genèse 2.24).')$c173$;
  execute $c174$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 3, 'L''Éternel lui-même', '« L''Éternel a été témoin entre toi et la femme de ta jeunesse… la femme de ton alliance » (Malachie 2.14).')$c174$;
  execute $c175$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 4, 'Comme Christ a aimé l''Église et s''est livré pour elle', '« Maris, aimez vos femmes, comme Christ a aimé l''Église, et s''est livré lui-même pour elle » (Éphésiens 5.25).')$c175$;
  execute $c176$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 5, 'Se soumettre les uns aux autres dans la crainte de Christ', '« Vous soumettant les uns aux autres dans la crainte de Christ » (Éphésiens 5.21) : la soumission s''inscrit dans un cadre mutuel.')$c176$;
  execute $c177$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 6, 'Faux', 'Faux : le mari est appelé à aimer comme Christ et à ne pas s''aigrir contre sa femme (Colossiens 3.19) ; les victimes de violence doivent être protégées.')$c177$;
  execute $c178$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 7, 'Fabricants de tentes', 'Paul demeura chez eux et travailla avec eux, car ils étaient faiseurs de tentes (Actes 18.3).')$c178$;
  execute $c179$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 8, 'Ils l''ont pris avec eux et lui ont exposé plus exactement la voie de Dieu', '« Ils le prirent avec eux, et lui exposèrent plus exactement la voie de Dieu » (Actes 18.26).')$c179$;
  execute $c180$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 9, 'Comme deux dons particuliers de Dieu', '« Chacun tient de Dieu un don particulier, l''un d''une manière, l''autre d''une autre » (1 Corinthiens 7.7).')$c180$;
  execute $c181$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 10, 'Sa sanctification, et qu''il s''abstienne de l''impudicité', '« Ce que Dieu veut, c''est votre sanctification ; c''est que vous vous absteniez de l''impudicité » (1 Thessaloniciens 4.3).')$c181$;
  execute $c182$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 11, 'Toute relation sexuelle hors du mariage', 'Porneia est un terme large qui couvre toute relation sexuelle en dehors du mariage.')$c182$;
  execute $c183$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 12, 'Il ne voulait pas pécher contre Dieu', '« Comment ferais-je un aussi grand mal et pécherais-je contre Dieu ? » (Genèse 39.9).')$c183$;
  execute $c184$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 13, 'Il lui a laissé son vêtement et s''est enfui', '« Il lui laissa son vêtement dans la main, et s''enfuit au dehors » (Genèse 39.12).')$c184$;
  execute $c185$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 14, 'Ne pas réveiller l''amour avant qu''il le veuille', '« Ne réveillez pas, ne réveillez pas l''amour, avant qu''elle le veuille » (Cantique 2.7).')$c185$;
  execute $c186$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 15, 'À la maison, en voyage, au coucher et au lever', 'Moïse cite quatre moments ordinaires : à la maison, en voyage, au coucher et au lever, c''est-à-dire partout et tout le temps.')$c186$;
  execute $c187$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 16, 'Aiguiser par des passages répétés', 'Shanan signifie aiguiser : on transmet la foi par une répétition patiente, comme on affûte une lame.')$c187$;
  execute $c188$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 17, 'Parce qu''il honorait ses fils plus que Dieu et ne les réprimait pas', '« Pourquoi honores-tu tes fils plus que moi ? » (1 Samuel 2.29) ; Éli connaissait leur mal sans les réprimer (1 Samuel 3.13).')$c188$;
  execute $c189$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 18, 'D''irriter leurs enfants', '« Pères, n''irritez pas vos enfants, mais élevez-les en les corrigeant et en les instruisant selon le Seigneur » (Éphésiens 6.4).')$c189$;
  execute $c190$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m3', 19, 'Vrai', 'Vrai : Paul évoque « la foi sincère… qui habita d''abord dans ton aïeule Loïs et dans ta mère Eunice » (2 Timothée 1.5).')$c190$;
  execute $c191$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n2m4', 2, 10, 3)$c191$;
  execute $c192$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 0, 'À l’Éternel', '« A l’Éternel la terre et ce qu’elle renferme » (Psaume 24.1) : Dieu est propriétaire parce qu’il est créateur.')$c192$;
  execute $c193$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 1, 'Celui qui gère la maison d’un autre et lui rend compte', 'L’oikonomos administre les biens de son maître ; c’est la position du chrétien face à ses biens (Luc 16.1-2).')$c193$;
  execute $c194$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 2, 'Dieu et Mamon', '« Vous ne pouvez servir Dieu et Mamon » (Matthieu 6.24) : Mamon désigne la richesse devenue un maître.')$c194$;
  execute $c195$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 3, 'Il l’a caché dans la terre', 'Par peur, il a creusé la terre et caché le talent de son maître (Matthieu 25.18, 25).')$c195$;
  execute $c196$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 4, 'La même louange : « C’est bien, bon et fidèle serviteur »', 'Le maître leur adresse exactement les mêmes paroles (Matthieu 25.21, 23) : il récompense la fidélité, non la comparaison des résultats.')$c196$;
  execute $c197$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 5, 'L’est aussi dans les grandes', '« Celui qui est fidèle dans les moindres choses l’est aussi dans les grandes » (Luc 16.10).')$c197$;
  execute $c198$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 6, 'L’amour de l’argent', 'Ce n’est pas l’argent lui-même, mais « l’amour de l’argent » qui est une racine de tous les maux (1 Timothée 6.10).')$c198$;
  execute $c199$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 7, 'Prendre ses deux enfants comme esclaves', '« Le créancier est venu pour prendre mes deux enfants et en faire ses esclaves » (2 Rois 4.1).')$c199$;
  execute $c200$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 8, 'Vendre l’huile, payer la dette et vivre du reste', '« Va vendre l’huile, et paie ta dette ; et tu vivras, toi et tes fils, de ce qui restera » (2 Rois 4.7).')$c200$;
  execute $c201$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 9, 'L’esclave de celui qui prête', '« Celui qui emprunte est l’esclave de celui qui prête » (Proverbes 22.7) : la dette restreint la liberté.')$c201$;
  execute $c202$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 10, 'À l’abondance', '« Les projets de l’homme diligent ne mènent qu’à l’abondance, mais celui qui agit avec précipitation n’arrive qu’à la disette. »')$c202$;
  execute $c203$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 11, 'Avec joie', '« Que chacun donne… sans tristesse ni contrainte ; car Dieu aime celui qui donne avec joie » (2 Corinthiens 9.7).')$c203$;
  execute $c204$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 12, 'Malgré leur pauvreté profonde, au-delà de leurs moyens et avec joie', 'Paul souligne leur joie et leur générosité au milieu de beaucoup de tribulations et malgré leur pauvreté profonde.')$c204$;
  execute $c205$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 13, 'Apportez-les à la maison du trésor et mettez-moi à l’épreuve', '« Apportez à la maison du trésor toutes les dîmes… Mettez-moi de la sorte à l’épreuve » (Malachie 3.10).')$c205$;
  execute $c206$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 14, 'Par donner à Dieu', 'Donner d’abord proclame que Dieu est premier (Proverbes 3.9), puis on épargne, on paie ses obligations et on vit avec le reste.')$c206$;
  execute $c207$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 15, 'Pour le cultiver et pour le garder', '« L’Éternel Dieu… le plaça dans le jardin d’Éden pour le cultiver et pour le garder » (Genèse 2.15), avant même le péché.')$c207$;
  execute $c208$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 16, 'Faux', 'Faux : le travail existait avant la chute (Genèse 2.15). Après le péché, c’est le sol qui est maudit et le travail devient pénible (Genèse 3.17-19).')$c208$;
  execute $c209$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 17, 'De bon cœur, comme pour le Seigneur', '« Tout ce que vous faites, faites-le de bon cœur, comme pour le Seigneur et non pour des hommes » (Colossiens 3.23).')$c209$;
  execute $c210$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 18, 'Faux', 'Faux : le texte vise celui qui ne veut pas travailler. Envers ceux qui ne peuvent pas, la Bible demande la solidarité.')$c210$;
  execute $c211$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m4', 19, 'Prélever le cinquième des récoltes pendant l’abondance et le stocker', 'Joseph conseille de prélever le cinquième des récoltes pendant les sept années d’abondance et de les garder en réserve (Genèse 41.34-36).')$c211$;
  execute $c212$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n2m5', 2, 11, 3)$c212$;
  execute $c213$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 0, 'Septante fois sept fois', 'Jésus répond à Pierre : « Je ne te dis pas jusqu’à sept fois, mais jusqu’à septante fois sept fois », c’est-à-dire sans compter.')$c213$;
  execute $c214$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 1, 'Dix mille talents', 'Il devait dix mille talents, une dette impossible à rembourser, que le roi lui a entièrement remise (Matthieu 18.24, 27).')$c214$;
  execute $c215$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 2, 'Il le fait jeter en prison', 'Il le saisit à la gorge et le fait jeter en prison jusqu’à ce qu’il ait payé (Matthieu 18.28-30).')$c215$;
  execute $c216$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 3, 'Celui qui a reçu un immense pardon de Dieu doit pardonner aux autres', '« Ne devais-tu pas aussi avoir pitié de ton compagnon, comme j’ai eu pitié de toi ? » (Matthieu 18.33).')$c216$;
  execute $c217$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 4, 'Comme Dieu nous a pardonné en Christ', '« Vous pardonnant réciproquement, comme Dieu vous a pardonné en Christ » (Éphésiens 4.32).')$c217$;
  execute $c218$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 5, 'Remettre la dette à Dieu et renoncer à la vengeance', 'Pardonner, c’est renoncer à la vengeance et remettre la cause à Dieu, qui juge justement (Romains 12.19), sans nier le mal.')$c218$;
  execute $c219$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 6, '« Vous aviez médité de me faire du mal, Dieu l’a changé en bien »', 'Joseph nomme le mal et reconnaît que Dieu l’a changé en bien pour sauver la vie à un peuple nombreux (Genèse 50.20).')$c219$;
  execute $c220$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 7, 'Faux', 'Faux : le pardon dépend de moi, la réconciliation demande un vrai changement ; se mettre en sécurité est juste, comme David qui fuit Saül.')$c220$;
  execute $c221$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 8, 'Ne pas pécher et ne pas laisser le soleil se coucher sur sa colère', '« Si vous vous mettez en colère, ne péchez point ; que le soleil ne se couche pas sur votre colère » (Éphésiens 4.26).')$c221$;
  execute $c222$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 9, 'Que le péché se couche à la porte, mais qu’il doit dominer sur lui', '« Le péché se couche à la porte, et ses désirs se portent vers toi : mais toi, domine sur lui » (Genèse 4.7).')$c222$;
  execute $c223$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 10, 'Prompt à écouter, lent à parler, lent à se mettre en colère', '« Que tout homme soit prompt à écouter, lent à parler, lent à se mettre en colère ; car la colère de l’homme n’accomplit pas la justice de Dieu. »')$c223$;
  execute $c224$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 11, 'Faux', 'Faux : Jésus s’est indigné (Marc 3.5) et Paul dit « si vous vous mettez en colère, ne péchez point ». C’est ce que l’on fait de sa colère qui peut devenir péché.')$c224$;
  execute $c225$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 12, 'Il lui parle et l’exhorte à espérer en Dieu', '« Pourquoi t’abats-tu, mon âme… ? Espère en Dieu, car je le louerai encore » (Psaume 42.6).')$c225$;
  execute $c226$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 13, 'Faire connaître ses besoins à Dieu par la prière, avec des actions de grâces', '« Ne vous inquiétez de rien ; mais en toute chose faites connaître vos besoins à Dieu par des prières et des supplications, avec des actions de grâces. »')$c226$;
  execute $c227$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 14, 'Elle gardera nos cœurs et nos pensées en Jésus-Christ', 'La paix de Dieu « gardera vos cœurs et vos pensées en Jésus-Christ » ; le verbe évoque une garnison qui monte la garde.')$c227$;
  execute $c228$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 15, 'Sage', '« Celui qui fréquente les sages devient sage, mais celui qui se plaît avec les insensés s’en trouve mal » (Proverbes 13.20).')$c228$;
  execute $c229$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 16, 'Le reprendre entre lui et nous seuls', '« Va et reprends-le entre toi et lui seul. S’il t’écoute, tu as gagné ton frère » (Matthieu 18.15).')$c229$;
  execute $c230$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 17, 'S’il est possible, autant que cela dépend de nous', '« S’il est possible, autant que cela dépend de vous, soyez en paix avec tous les hommes » : je suis responsable de ma part.')$c230$;
  execute $c231$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 18, 'Il lui a donné son manteau, ses vêtements et ses armes', 'Jonathan se dépouilla de son manteau, de ses vêtements, de son épée, de son arc et de sa ceinture pour les donner à David.')$c231$;
  execute $c232$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m5', 19, 'Il s’est enfui pour se mettre en sécurité', 'Averti par le signal des flèches, David s’est enfui (1 Samuel 20.35-42) : se protéger d’une personne violente est sage.')$c232$;
  execute $c233$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n2m6', 2, 12, 3)$c233$;
  execute $c234$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 0, 'Le temple du Saint-Esprit', '« Votre corps est le temple du Saint-Esprit qui est en vous » (1 Corinthiens 6.19).')$c234$;
  execute $c235$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 1, 'Parce que nous avons été rachetés à un grand prix', '« Vous avez été rachetés à un grand prix. Glorifiez donc Dieu dans votre corps » : le prix est le sang de Christ.')$c235$;
  execute $c236$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 2, 'Le sanctuaire où Dieu habite', 'Naos désigne le sanctuaire lui-même, le lieu de la présence de Dieu, et non l’ensemble des bâtiments du temple.')$c236$;
  execute $c237$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 3, 'Des légumes et de l’eau', 'Daniel demande : « qu’on nous donne des légumes à manger et de l’eau à boire » (Daniel 1.12).')$c237$;
  execute $c238$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 4, 'L’exercice corporel est utile à peu de chose, la piété est utile à tout', '« L’exercice corporel est utile à peu de chose, tandis que la piété est utile à tout » : une hiérarchie, pas une opposition.')$c238$;
  execute $c239$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 5, 'Est compatible avec la prière et la foi', 'Luc était « le médecin bien-aimé » (Colossiens 4.14) ; Dieu peut guérir par des moyens ordinaires ou extraordinaires.')$c239$;
  execute $c240$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 6, 'Faux', 'Faux : c’est un souhait de Jean pour Gaïus, selon une formule de salutation courante, qui montre le souci des apôtres pour la santé de leurs frères.')$c240$;
  execute $c241$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 7, 'Sur le fait qu’il s’est reposé le septième jour après la création', '« En six jours l’Éternel a fait les cieux, la terre et la mer… et il s’est reposé le septième jour » (Exode 20.11).')$c241$;
  execute $c242$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 8, 'Le souvenir de l’esclavage en Égypte et de la délivrance', '« Tu te souviendras que tu as été esclave au pays d’Égypte… c’est pourquoi l’Éternel, ton Dieu, t’a ordonné d’observer le jour du repos. »')$c242$;
  execute $c243$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 9, 'On en ramassait une double portion pour le jour du repos', 'Le sixième jour, chacun ramassait le double, car le septième jour il n’y avait pas de manne (Exode 16.22-26).')$c243$;
  execute $c244$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 10, 'Le sabbat a été fait pour l’homme, et non l’homme pour le sabbat', '« Le sabbat a été fait pour l’homme, et non l’homme pour le sabbat » : le repos est un don pour le bien de l’homme.')$c244$;
  execute $c245$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 11, 'Venez à l’écart dans un lieu désert, et reposez-vous un peu', 'Ils n’avaient « pas même le temps de manger » ; Jésus les invite à se reposer à l’écart (Marc 6.31).')$c245$;
  execute $c246$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 12, 'À ceux qui sont fatigués et chargés et qui viennent à lui', '« Venez à moi, vous tous qui êtes fatigués et chargés, et je vous donnerai du repos » (Matthieu 11.28).')$c246$;
  execute $c247$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 13, 'Faux', 'Faux : Dieu lui-même s’est reposé et a commandé le repos. Le paresseux refuse de travailler ; celui qui se repose fait confiance à Dieu.')$c247$;
  execute $c248$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 14, 'Parce que la reine Jézabel menace de le tuer', 'Jézabel lui envoie un message de mort ; Élie a peur et s’enfuit pour sauver sa vie (1 Rois 19.1-3).')$c248$;
  execute $c249$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 15, 'Il l’a fait dormir et manger', 'Un ange le touche deux fois et lui dit : « Lève-toi, mange, car le chemin est trop long pour toi » (1 Rois 19.5-7).')$c249$;
  execute $c250$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 16, 'Dans un murmure doux et léger', 'L’Éternel n’était ni dans le vent, ni dans le tremblement de terre, ni dans le feu ; après le feu vint « un murmure doux et léger » (1 Rois 19.11-12).')$c250$;
  execute $c251$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 17, 'En lui révélant qu’il s’était réservé sept mille hommes fidèles', 'Dieu révèle qu’il s’est réservé en Israël sept mille hommes qui n’ont pas fléchi le genou devant Baal (1 Rois 19.18).')$c251$;
  execute $c252$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 18, 'De ceux qui ont le cœur brisé', '« L’Éternel est près de ceux qui ont le cœur brisé, et il sauve ceux qui ont l’esprit dans l’abattement » (Psaume 34.19).')$c252$;
  execute $c253$insert into public.cles_examen (module_id, question, reponse, explication) values ('n2m6', 19, 'Faux', 'Faux : Élie, Job, Jérémie, David et Paul ont connu de grandes détresses. Demander de l’aide est un acte de sagesse (Galates 6.2).')$c253$;
  execute $c254$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n3m1', 3, 13, 3)$c254$;
  execute $c255$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 0, 'Ils sont créés à l’image de Dieu', '« Dieu créa l’homme à son image… il créa l’homme et la femme » (Genèse 1.27) : tous deux portent également l’image de Dieu.')$c255$;
  execute $c256$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 1, '« Dieu a-t-il réellement dit… ? »', 'Le serpent commence par mettre en doute la parole de Dieu (Genèse 3.1). « Où es-tu ? » est la question de Dieu à Adam (Genèse 3.9).')$c256$;
  execute $c257$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 2, 'Créer, une œuvre que seul Dieu accomplit', 'Dans l’Ancien Testament, bārā’ a toujours Dieu pour sujet : il désigne l’acte créateur que lui seul peut accomplir.')$c257$;
  execute $c258$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 3, 'Par la foi', '« C’est par la foi que nous reconnaissons que le monde a été formé par la parole de Dieu » (Hébreux 11.3).')$c258$;
  execute $c259$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 4, 'Par un seul homme', '« Par un seul homme le péché est entré dans le monde, et par le péché la mort » (Romains 5.12).')$c259$;
  execute $c260$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 5, 'Genèse 3.15', 'En Genèse 3.15, Dieu annonce que la postérité de la femme écrasera la tête du serpent : une promesse accomplie en Christ.')$c260$;
  execute $c261$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 6, 'Création, chute, rédemption, restauration', 'La Bible raconte la création bonne, la chute de l’homme, la rédemption en Christ et la restauration de toutes choses (Apocalypse 21.5).')$c261$;
  execute $c262$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 7, 'Être déclaré juste par Dieu par la foi en Christ', 'Justifier (grec dikaioō) signifie déclarer juste : « ils sont gratuitement justifiés par sa grâce » (Romains 3.24).')$c262$;
  execute $c263$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 8, 'La transformation progressive du croyant par le Saint-Esprit', 'La sanctification est l’œuvre continue de l’Esprit qui nous rend semblables à Christ ; elle découle de la justification sans la remplacer.')$c263$;
  execute $c264$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 9, 'Un seul : Jésus-Christ homme', '« Il y a un seul Dieu, et aussi un seul médiateur entre Dieu et les hommes, Jésus-Christ homme » (1 Timothée 2.5).')$c264$;
  execute $c265$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 10, 'Jésus a pris notre place et porté notre péché', '« Celui qui n’a point connu le péché, il l’a fait devenir péché pour nous, afin que nous devenions en lui justice de Dieu » (2 Corinthiens 5.21).')$c265$;
  execute $c266$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 11, 'Le publicain', 'Jésus conclut : « celui-ci [le publicain] descendit dans sa maison justifié, plutôt que l’autre » (Luc 18.14).')$c266$;
  execute $c267$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 12, 'Avec son propre sang', 'Christ est entré « une fois pour toutes dans le lieu très saint, non avec le sang des boucs et des veaux, mais avec son propre sang » (Hébreux 9.12).')$c267$;
  execute $c268$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 13, 'Selon sa miséricorde', '« Il nous a sauvés, non à cause des œuvres de justice que nous aurions faites, mais selon sa miséricorde » (Tite 3.5).')$c268$;
  execute $c269$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 14, 'Vrai', 'Romains 8.30 relie appel, justification et glorification en une chaîne que rien ne brise : « ceux qu’il a justifiés, il les a aussi glorifiés ».')$c269$;
  execute $c270$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 15, 'Les portes du séjour des morts', '« Je bâtirai mon Église, et les portes du séjour des morts ne prévaudront point contre elle » (Matthieu 16.18).')$c270$;
  execute $c271$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 16, 'Une assemblée de personnes convoquées', 'L’ekklēsia est l’assemblée de ceux que Dieu appelle ; l’Église est un peuple avant d’être un lieu.')$c271$;
  execute $c272$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 17, 'Il est triste, mais pas comme ceux qui n’ont point d’espérance', 'Paul écrit « afin que vous ne vous affligiez pas comme les autres qui n’ont point d’espérance » : le chrétien pleure, mais avec espérance.')$c272$;
  execute $c273$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 18, '« Je suis la résurrection et la vie »', '« Je suis la résurrection et la vie. Celui qui croit en moi vivra, quand même il serait mort » (Jean 11.25).')$c273$;
  execute $c274$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m1', 19, 'Un nouveau ciel et une nouvelle terre où Dieu habite avec les hommes', 'Jean voit « un nouveau ciel et une nouvelle terre » et entend : « Voici le tabernacle de Dieu avec les hommes ! » (Apocalypse 21.1-3).')$c274$;
  execute $c275$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n3m2', 3, 14, 3)$c275$;
  execute $c276$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 0, 'Un texte hors contexte peut dire le contraire de son sens', 'Un texte sans contexte devient un prétexte : le diable lui-même a cité le Psaume 91 en le détournant (Matthieu 4.6).')$c276$;
  execute $c277$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 1, 'Le Psaume 91', 'Le diable cite le Psaume 91.11-12 en omettant « dans toutes tes voies » et en le transformant en invitation à tenter Dieu.')$c277$;
  execute $c278$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 2, '« Il est aussi écrit : Tu ne tenteras point le Seigneur, ton Dieu »', 'Jésus interprète l’Écriture par l’Écriture en citant Deutéronome 6.16.')$c278$;
  execute $c279$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 3, 'Ils examinaient chaque jour les Écritures pour vérifier ce qu’on leur disait', 'Ils reçurent la parole avec empressement et examinaient chaque jour les Écritures « pour voir si ce qu’on leur disait était exact ».')$c279$;
  execute $c280$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 4, 'Ils en donnaient le sens pour faire comprendre ce qui était lu', '« Ils en donnaient le sens pour faire comprendre ce qu’ils avaient lu » (Néhémie 8.8).')$c280$;
  execute $c281$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 5, 'Couper droit, tracer un chemin droit', 'Orthotomeō signifie couper droit : l’interprète fidèle trace un chemin droit à travers le texte.')$c281$;
  execute $c282$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 6, 'D’apprendre le contentement dans l’abondance comme dans la disette', 'Les versets 11-12 parlent de savoir vivre dans l’humiliation et dans l’abondance : Christ fortifie Paul dans toutes les situations.')$c282$;
  execute $c283$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 7, 'Aux exilés de Babylone, qui devaient y rester soixante-dix ans', 'Le verset suit l’annonce que l’exil durera soixante-dix ans (Jérémie 29.10) : la promesse inclut une longue attente.')$c283$;
  execute $c284$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 8, 'Comme une affaire réelle à juger', 'David s’indigne et condamne le riche, jusqu’à ce que Nathan lui dise : « Tu es cet homme-là ! » (2 Samuel 12.7).')$c284$;
  execute $c285$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 9, 'Des principes généraux de sagesse', 'Un māshāl est une maxime de sagesse qui dit ce qui arrive généralement ; Proverbes 26.4-5 montre qu’il faut discerner quand l’appliquer.')$c285$;
  execute $c286$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 10, 'Que la sagesse consiste à discerner quelle maxime s’applique à chaque situation', 'Les proverbes ne sont pas des règles mécaniques : parfois il faut se taire, parfois répondre, selon la situation.')$c286$;
  execute $c287$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 11, 'Le parallélisme des idées d’une ligne à l’autre', 'La poésie hébraïque reprend, prolonge ou oppose une idée dans la ligne suivante : « Il me fait reposer… Il me dirige… ».')$c287$;
  execute $c288$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 12, 'Les sept Églises', '« Les sept étoiles sont les anges des sept Églises, et les sept chandeliers sont les sept Églises » (Apocalypse 1.20).')$c288$;
  execute $c289$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 13, 'Faux', 'Faux. La Bible raconte par exemple l’adultère de David, mais précise : « Ce que David avait fait déplut à l’Éternel » (2 Samuel 11.27).')$c289$;
  execute $c290$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 14, 'Par Moïse et par tous les prophètes', '« Et, commençant par Moïse et par tous les prophètes, il leur expliqua dans toutes les Écritures ce qui le concernait » (Luc 24.27).')$c290$;
  execute $c291$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 15, 'De Jésus-Christ', '« Vous sondez les Écritures… ce sont elles qui rendent témoignage de moi » (Jean 5.39).')$c291$;
  execute $c292$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 16, 'Sens premier, principe intemporel, application', 'Hier, toujours, aujourd’hui : ce que le texte signifiait, le principe qui demeure, puis son application à notre vie.')$c292$;
  execute $c293$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 17, 'Qu’on utilise les passages clairs pour éclairer les passages difficiles', 'Puisque toute l’Écriture vient du même Dieu, on éclaire les textes obscurs par les textes clairs, sans bâtir de doctrine sur un verset isolé.')$c293$;
  execute $c294$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 18, 'Prendre des mesures pour protéger la sécurité des autres, par exemple autour d’une piscine ou sur un chantier', 'Le principe : je suis responsable de la sécurité de ceux qui sont affectés par mes biens et mes actes, par amour du prochain.')$c294$;
  execute $c295$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m2', 19, 'À un homme qui se regarde dans un miroir puis oublie son visage', 'Jacques compare l’auditeur oublieux à un homme qui se regarde dans un miroir et oublie aussitôt quel il était (Jacques 1.23-24).')$c295$;
  execute $c296$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n3m3', 3, 15, 3)$c296$;
  execute $c297$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 0, 'Faire de toutes les nations des disciples', '« Allez, faites de toutes les nations des disciples, les baptisant… et enseignez-leur à observer tout ce que je vous ai prescrit » (Matthieu 28.19-20).')$c297$;
  execute $c298$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 1, 'Sur l’autorité de Jésus, à qui tout pouvoir a été donné dans le ciel et sur la terre', '« Tout pouvoir m’a été donné dans le ciel et sur la terre. Allez… » : la mission découle de l’autorité de Christ.')$c298$;
  execute $c299$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 2, '« Je suis avec vous tous les jours, jusqu’à la fin du monde »', 'Matthieu termine son Évangile par la présence de Jésus avec ses disciples, comme il l’avait commencé avec « Emmanuel, Dieu avec nous ».')$c299$;
  execute $c300$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 3, 'Tous les disciples', 'Jésus dit à tous ses disciples : « vous serez mes témoins » (Actes 1.8) ; dans les Actes, les croyants dispersés annonçaient la parole partout (Actes 8.4).')$c300$;
  execute $c301$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 4, 'La puissance du Saint-Esprit survenant sur eux', '« Vous recevrez une puissance, le Saint-Esprit survenant sur vous, et vous serez mes témoins » (Actes 1.8).')$c301$;
  execute $c302$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 5, 'Jérusalem, la Judée, la Samarie, les extrémités de la terre', '« À Jérusalem, dans toute la Judée, dans la Samarie, et jusqu’aux extrémités de la terre » : un plan qui structure tout le livre des Actes.')$c302$;
  execute $c303$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 6, 'Dans sa maison, vers les siens, pour raconter ce que le Seigneur a fait', '« Va dans ta maison, vers les tiens, et raconte-leur tout ce que le Seigneur t’a fait, et comment il a eu pitié de toi » (Marc 5.19).')$c303$;
  execute $c304$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 7, 'Ils ne le peuvent pas : il faut que quelqu’un prêche', 'Paul établit une chaîne : être envoyé, prêcher, entendre, croire, invoquer. « Comment en entendront-ils parler, s’il n’y a personne qui prêche ? »')$c304$;
  execute $c305$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 8, 'Celui qui atteste ce qu’il a vu et vécu', 'Le témoin raconte ce qu’il a vu ; le mot a aussi donné « martyr », pour ceux qui ont scellé leur témoignage de leur vie.')$c305$;
  execute $c306$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 9, 'Christ est mort pour nos péchés, a été enseveli et est ressuscité le troisième jour', '« Christ est mort pour nos péchés, selon les Écritures ; il a été enseveli, et il est ressuscité le troisième jour, selon les Écritures. »')$c306$;
  execute $c307$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 10, 'Avec douceur et respect', '« Étant toujours prêts à vous défendre, avec douceur et respect, devant quiconque vous demande raison de l’espérance qui est en vous. »')$c307$;
  execute $c308$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 11, 'Une plaidoirie, une défense raisonnée', 'Apologia est la défense présentée au tribunal ; il a donné « apologétique », l’explication raisonnée de la foi.')$c308$;
  execute $c309$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 12, 'En lui demandant à boire', '« Donne-moi à boire » (Jean 4.7) : Jésus prend l’initiative, franchit les barrières et part d’un besoin concret.')$c309$;
  execute $c310$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 13, '« Venez voir un homme qui m’a dit tout ce que j’ai fait ; ne serait-ce point le Christ ? »', 'Elle laisse sa cruche et invite toute la ville à venir voir Jésus (Jean 4.28-29) ; beaucoup crurent.')$c310$;
  execute $c311$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 14, 'Amour de Dieu, péché, croix, réponse de foi', 'Dieu nous aime (Jean 3.16), le péché nous sépare de lui (Romains 3.23), Jésus est mort et ressuscité (1 Corinthiens 15.3-4), il faut se repentir et croire (Marc 1.15).')$c311$;
  execute $c312$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 15, 'Le prophète Ésaïe', 'Il lisait Ésaïe 53 (Actes 8.28-33), et Philippe, « commençant par ce passage, lui annonça la bonne nouvelle de Jésus ».')$c312$;
  execute $c313$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 16, '« Comment le pourrais-je, si quelqu’un ne me guide ? »', 'Il reconnaît humblement son besoin d’un guide et invite Philippe à monter et à s’asseoir avec lui.')$c313$;
  execute $c314$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 17, 'Faux', 'Faux. Le grand mandat demande de faire des disciples en les baptisant et en leur enseignant à obéir ; il faut accompagner, enseigner et intégrer dans l’Église.')$c314$;
  execute $c315$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 18, 'À une nourrice qui prend un tendre soin de ses enfants', 'Paul a été doux comme une nourrice, donnant non seulement l’Évangile mais sa propre vie, tant les Thessaloniciens lui étaient chers.')$c315$;
  execute $c316$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m3', 19, 'À des hommes fidèles, capables de l’enseigner aussi à d’autres', '« Confie-le à des hommes fidèles, qui soient capables de l’enseigner aussi à d’autres » : gagner, affermir, envoyer.')$c316$;
  execute $c317$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n3m4', 3, 16, 3)$c317$;
  execute $c318$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 0, 'Contre les dominations, les autorités et les esprits méchants dans les lieux célestes', 'Éphésiens 6.12 : nous n’avons pas à lutter contre la chair et le sang, mais contre des puissances spirituelles.')$c318$;
  execute $c319$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 1, 'Calomniateur, accusateur', 'Diabolos signifie calomniateur ou accusateur ; Apocalypse 12.10 l’appelle l’accusateur de nos frères.')$c319$;
  execute $c320$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 2, 'Il ne peut agir contre Job que dans les limites fixées par Dieu', 'Job 1.12 et 2.6 : Dieu fixe des limites (« ne porte pas la main sur lui », « épargne sa vie »).')$c320$;
  execute $c321$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 3, 'La sobriété, la vigilance et la résistance avec une foi ferme', 'Pierre dit : « Soyez sobres, veillez… Résistez-lui avec une foi ferme ».')$c321$;
  execute $c322$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 4, 'Pour dérober, égorger et détruire', 'Jean 10.10 : le voleur ne vient que pour dérober, égorger et détruire ; Jésus vient donner la vie en abondance.')$c322$;
  execute $c323$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 5, 'Des méthodes, des stratégies habiles', 'Methodeia désigne des plans et des stratégies ; l’ennemi agit souvent par la ruse.')$c323$;
  execute $c324$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 6, 'L’épée de l’Esprit', 'Éphésiens 6.17 : « l’épée de l’Esprit, qui est la parole de Dieu ».')$c324$;
  execute $c325$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 7, 'Le bouclier de la foi', 'Éphésiens 6.16 : le bouclier de la foi permet d’éteindre tous les traits enflammés du malin.')$c325$;
  execute $c326$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 8, 'En citant l’Écriture : « Il est écrit »', 'À chaque tentation, Jésus répond « Il est écrit » en citant le Deutéronome.')$c326$;
  execute $c327$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 9, 'Se soumettre à Dieu', 'Jacques 4.7 : « Soumettez-vous donc à Dieu ; résistez au diable, et il fuira loin de vous ».')$c327$;
  execute $c328$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 10, 'Des raisonnements et toute hauteur qui s’élève contre la connaissance de Dieu', 'Paul parle de renverser les raisonnements et d’amener toute pensée captive à l’obéissance de Christ.')$c328$;
  execute $c329$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 11, 'Elle donne accès au diable', 'Paul dit : que le soleil ne se couche pas sur votre colère, et ne donnez pas accès au diable.')$c329$;
  execute $c330$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 12, 'Par la croix', 'Colossiens 2.15 : il les a livrées publiquement en spectacle, en triomphant d’elles par la croix.')$c330$;
  execute $c331$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 13, 'L’acte dont les ordonnances nous condamnaient', 'Colossiens 2.14 : il a effacé l’acte qui nous condamnait et l’a détruit en le clouant à la croix.')$c331$;
  execute $c332$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 14, 'Par le sang de l’Agneau, la parole de leur témoignage et le refus de craindre la mort', 'Apocalypse 12.11 : ils l’ont vaincu à cause du sang de l’agneau et de la parole de leur témoignage, et n’ont pas aimé leur vie jusqu’à craindre la mort.')$c332$;
  execute $c333$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 15, 'De ce que leurs noms sont écrits dans les cieux', 'Jésus dit : ne vous réjouissez pas de ce que les esprits vous sont soumis, mais de ce que vos noms sont écrits dans les cieux.')$c333$;
  execute $c334$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 16, 'Que l’autorité spirituelle vient d’une relation avec Christ, non d’une formule', 'L’esprit répondit : « Je connais Jésus, et je sais qui est Paul ; mais vous, qui êtes-vous ? »')$c334$;
  execute $c335$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 17, 'Assis, vêtu et dans son bon sens', 'Marc 5.15 : les gens le trouvèrent assis, vêtu, et dans son bon sens ; Jésus l’envoya témoigner aux siens.')$c335$;
  execute $c336$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 18, 'Faux', 'Faux. La Bible parle aussi de la chair, du monde, de nos choix et de la vie dans un monde déchu ; il faut être sobre (1 Pierre 5.8).')$c336$;
  execute $c337$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m4', 19, 'Vrai', 'Vrai. Par sa mort, il a anéanti celui qui avait la puissance de la mort et délivré ceux qui étaient retenus par cette crainte.')$c337$;
  execute $c338$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n3m5', 3, 17, 3)$c338$;
  execute $c339$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 0, 'Pour servir et donner sa vie comme la rançon de plusieurs', 'Marc 10.45 : le Fils de l’homme est venu non pour être servi, mais pour servir et donner sa vie comme la rançon de plusieurs.')$c339$;
  execute $c340$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 1, 'Être assis à sa droite et à sa gauche dans sa gloire', 'Marc 10.37 : ils demandent d’être assis l’un à sa droite et l’autre à sa gauche dans sa gloire.')$c340$;
  execute $c341$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 2, 'L’esclave de tous', 'Jésus dit : quiconque veut être le premier parmi vous, qu’il soit l’esclave de tous.')$c341$;
  execute $c342$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 3, 'Le prix payé pour libérer un captif', 'Lytron, la rançon, désignait le prix payé pour libérer un esclave ou un prisonnier.')$c342$;
  execute $c343$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 4, 'Il refuse : « Non, jamais tu ne me laveras les pieds »', 'Jean 13.8 : Pierre dit « Non, jamais tu ne me laveras les pieds ».')$c343$;
  execute $c344$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 5, 'De se laver les pieds les uns aux autres, car il leur a donné un exemple', 'Jésus dit : vous devez aussi vous laver les pieds les uns aux autres ; car je vous ai donné un exemple.')$c344$;
  execute $c345$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 6, 'Regarder les autres comme étant au-dessus de soi-même', 'Philippiens 2.3 : que l’humilité vous fasse regarder les autres comme étant au-dessus de vous-mêmes.')$c345$;
  execute $c346$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 7, 'En prenant une forme de serviteur et en devenant semblable aux hommes', 'Il s’est dépouillé lui-même en prenant une forme de serviteur, en devenant semblable aux hommes, sans cesser d’être Dieu.')$c346$;
  execute $c347$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 8, 'Les veuves des Hellénistes étaient négligées dans la distribution quotidienne', 'Actes 6.1 : les Hellénistes murmuraient parce que leurs veuves étaient négligées dans la distribution quotidienne.')$c347$;
  execute $c348$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 9, 'Avoir un bon témoignage, être pleins d’Esprit-Saint et de sagesse', 'Actes 6.3 : des hommes de qui l’on rende un bon témoignage, pleins d’Esprit-Saint et de sagesse.')$c348$;
  execute $c349$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 10, 'La parole de Dieu se répandait et le nombre des disciples augmentait beaucoup', 'Actes 6.7 : la parole de Dieu se répandait de plus en plus et le nombre des disciples augmentait beaucoup à Jérusalem.')$c349$;
  execute $c350$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 11, 'Pour le perfectionnement des saints en vue de l’œuvre du ministère', 'Éphésiens 4.12 : pour le perfectionnement des saints en vue de l’œuvre du ministère et de l’édification du corps de Christ.')$c350$;
  execute $c351$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 12, 'Mettre en état, équiper, préparer à remplir sa fonction', 'Katartismos évoque la remise en état et l’équipement, comme pour réparer des filets de pêche.')$c351$;
  execute $c352$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 13, 'Un corps avec plusieurs membres', 'Romains 12.4-5 : comme nous avons plusieurs membres dans un seul corps, nous formons un seul corps en Christ.')$c352$;
  execute $c353$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 14, 'D’être trouvés fidèles', '1 Corinthiens 4.2 : ce qu’on demande des dispensateurs, c’est que chacun soit trouvé fidèle.')$c353$;
  execute $c354$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 15, 'Si nous ne nous relâchons pas', 'Galates 6.9 : nous moissonnerons au temps convenable, si nous ne nous relâchons pas.')$c354$;
  execute $c355$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 16, 'Il lui a donné à manger et l’a laissé dormir', '1 Rois 19.5-7 : un ange le toucha et lui dit « Lève-toi, mange », et il se recoucha ; Dieu prit soin de son corps.')$c355$;
  execute $c356$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 17, 'Parce qu’il avait enterré son talent par peur et paresse', 'Il n’est pas blâmé d’avoir peu reçu, mais d’avoir caché son talent au lieu de le faire fructifier.')$c356$;
  execute $c357$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 18, 'Faux', 'Faux. En Actes 6, servir aux tables est un vrai ministère, et 1 Corinthiens 12.22 dit que les membres qui paraissent les plus faibles sont nécessaires.')$c357$;
  execute $c358$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m5', 19, 'Vrai', 'Vrai. Paul dit : sachant que votre travail ne sera pas vain dans le Seigneur.')$c358$;
  execute $c359$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n3m6', 3, 18, 3)$c359$;
  execute $c360$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 0, 'Le sel de la terre et la lumière du monde', 'Matthieu 5.13-14 : « Vous êtes le sel de la terre… Vous êtes la lumière du monde. »')$c360$;
  execute $c361$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 1, 'Afin que les hommes voient leurs bonnes œuvres et glorifient le Père', 'Le but est que les hommes glorifient notre Père qui est dans les cieux.')$c361$;
  execute $c362$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 2, 'Paix et bien-être complet, prospérité, harmonie', 'Shalom désigne la paix au sens large : bien-être, prospérité, harmonie ; Dieu demande de rechercher le bien de la ville.')$c362$;
  execute $c363$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 3, 'Rechercher le bien de la ville et prier l’Éternel en sa faveur', 'Jérémie 29.7 : recherchez le bien de la ville… et priez l’Éternel en sa faveur, parce que votre bonheur dépend du sien.')$c363$;
  execute $c364$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 4, 'De ne pas se souiller par les mets et le vin du roi', 'Daniel 1.8 : Daniel résolut de ne pas se souiller par les mets du roi et par le vin dont le roi buvait.')$c364$;
  execute $c365$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 5, 'Par une demande respectueuse et la proposition d’un essai de dix jours', 'Daniel demanda poliment et proposa un essai de dix jours avec des légumes et de l’eau.')$c365$;
  execute $c366$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 6, 'Devenir fade, et aussi devenir fou ou insensé', 'Môrainô signifie devenir fade et aussi devenir insensé : un disciple sans différence perd sa raison d’être.')$c366$;
  execute $c367$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 7, 'Pratiquer la justice, aimer la miséricorde et marcher humblement avec Dieu', 'Michée 6.8 : que tu pratiques la justice, que tu aimes la miséricorde, et que tu marches humblement avec ton Dieu.')$c367$;
  execute $c368$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 8, 'L’amour fidèle et loyal de l’alliance', 'Hesed, traduit par « miséricorde », est la bonté fidèle et loyale de l’alliance.')$c368$;
  execute $c369$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 9, 'De Dieu, qui les a instituées', 'Romains 13.1 : il n’y a point d’autorité qui ne vienne de Dieu, et les autorités qui existent ont été instituées de Dieu.')$c369$;
  execute $c370$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 10, 'Rendre à tous ce qui leur est dû : l’impôt, le tribut, la crainte, l’honneur', 'Romains 13.7 : rendez à tous ce qui leur est dû : l’impôt à qui vous devez l’impôt…')$c370$;
  execute $c371$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 11, 'Quand l’autorité humaine ordonne clairement de désobéir à Dieu', 'Les apôtres désobéissent à l’ordre de ne plus enseigner au nom de Jésus, car il contredisait le commandement de Dieu.')$c371$;
  execute $c372$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 12, 'Ils se sont retirés joyeux d’avoir été jugés dignes de subir des outrages pour le nom de Jésus', 'Actes 5.41 : ils se retirèrent joyeux ; leur désobéissance était respectueuse et non violente.')$c372$;
  execute $c373$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 13, 'Qu’il donnerait aux pauvres la moitié de ses biens et rendrait le quadruple à ceux qu’il avait lésés', 'Luc 19.8 : je donne aux pauvres la moitié de mes biens, et si j’ai fait tort à quelqu’un, je lui rends le quadruple.')$c373$;
  execute $c374$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 14, 'La balance fausse', 'Proverbes 11.1 : la balance fausse est en horreur à l’Éternel, mais le poids juste lui est agréable.')$c374$;
  execute $c375$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 15, 'Le Samaritain', 'Le docteur de la loi répond : celui qui a exercé la miséricorde envers lui ; c’est le Samaritain.')$c375$;
  execute $c376$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 16, 'Au Roi lui-même', 'Matthieu 25.40 : c’est à moi que vous les avez faites.')$c376$;
  execute $c377$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 17, 'Morte en elle-même', 'Jacques 2.17 : si elle n’a pas les œuvres, elle est morte en elle-même.')$c377$;
  execute $c378$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 18, 'Faux', 'Faux. Exode 23.8 interdit les présents qui corrompent, et Proverbes 11.1 condamne la balance fausse, quelle que soit la norme sociale.')$c378$;
  execute $c379$insert into public.cles_examen (module_id, question, reponse, explication) values ('n3m6', 19, 'Vrai', 'Vrai. Galates 6.10 : pratiquons le bien envers tous, et surtout envers les frères en la foi.')$c379$;
  execute $c380$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n4m1', 4, 19, 3)$c380$;
  execute $c381$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 0, 'Le caractère', 'Sur une quinzaine de qualités demandées en 1 Timothée 3.2-7, presque toutes concernent le caractère ; une seule (« propre à l’enseignement ») porte sur une compétence.')$c381$;
  execute $c382$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 1, 'Qu’on ne peut saisir, sur qui l’accusation n’a pas prise', 'Anepilêmptos signifie « qu’on ne peut saisir » : une vie qui ne donne pas prise à une accusation fondée, sans être une perfection sans péché.')$c382$;
  execute $c383$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 2, 'Au cœur', '« L’homme regarde à ce qui frappe les yeux, mais l’Éternel regarde au coeur » (1 Samuel 16.7).')$c383$;
  execute $c384$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 3, 'Il faisait paître les brebis', 'Isaï dit : « Il reste encore le plus jeune, mais il fait paître les brebis » (1 Samuel 16.11).')$c384$;
  execute $c385$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 4, 'De peur qu’enflé d’orgueil il ne tombe sous le jugement du diable', 'Paul écrit : « Il ne faut pas qu’il soit un nouveau converti, de peur qu’enflé d’orgueil il ne tombe sous le jugement du diable » (1 Timothée 3.6).')$c385$;
  execute $c386$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 5, 'Économe de Dieu', '« Il faut que l’évêque soit irréprochable, comme économe de Dieu » (Tite 1.7) : il gère ce qui appartient à Dieu.')$c386$;
  execute $c387$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 6, 'Faux', 'Faux : « Qu’on les éprouve d’abord, et qu’ils exercent ensuite leur ministère, s’ils sont sans reproche » (1 Timothée 3.10).')$c387$;
  execute $c388$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 7, 'Je ne vous ai jamais connus', 'Jésus dit : « Je ne vous ai jamais connus, retirez-vous de moi, vous qui commettez l’iniquité » (Matthieu 7.23). Les dons ne prouvent pas, à eux seuls, une vie juste.')$c388$;
  execute $c389$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 8, 'Volontairement, avec dévouement et en étant les modèles du troupeau', 'Pierre écrit : « non par contrainte, mais volontairement… non pour un gain sordide, mais avec dévouement ; non comme dominant… mais en étant les modèles du troupeau ».')$c389$;
  execute $c390$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 9, 'Il leur résiste', '« Dieu résiste aux orgueilleux, Mais il fait grâce aux humbles » (1 Pierre 5.5, citant Proverbes 3.34).')$c390$;
  execute $c391$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 10, 'Tu es cet homme-là !', '« Et Nathan dit à David : Tu es cet homme-là ! » (2 Samuel 12.7).')$c391$;
  execute $c392$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 11, 'Il a dit : « J’ai péché contre l’Éternel ! »', '« David dit à Nathan : J’ai péché contre l’Éternel ! » (2 Samuel 12.13). C’est Saül qui, en 1 Samuel 15.30, avait demandé à être honoré devant les anciens.')$c392$;
  execute $c393$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 12, 'L’orgueil', '« L’arrogance précède la ruine, Et l’orgueil précède la chute » (Proverbes 16.18).')$c393$;
  execute $c394$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 13, 'Le serviteur des autres', '« Quiconque veut être grand parmi vous, qu’il soit votre serviteur ; et quiconque veut être le premier parmi vous, qu’il soit l’esclave de tous » (Marc 10.43-44).')$c394$;
  execute $c395$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 14, 'Faire compter et vérifier les fonds par plusieurs personnes et rendre compte de façon transparente', 'Paul recherchait « ce qui est bien, non seulement devant le Seigneur, mais aussi devant les hommes » (2 Corinthiens 8.21). Des garde-fous transparents protègent le leader et l’Église.')$c395$;
  execute $c396$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 15, 'À eux-mêmes, puis à tout le troupeau', '« Prenez donc garde à vous-mêmes, et à tout le troupeau sur lequel le Saint-Esprit vous a établis évêques » (Actes 20.28).')$c396$;
  execute $c397$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 16, 'Il sortit dans un lieu désert pour prier', '« Vers le matin, pendant qu’il faisait encore très sombre, il se leva, et sortit pour aller dans un lieu désert, où il pria » (Marc 1.35).')$c397$;
  execute $c398$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 17, 'Il le laisse dormir et lui donne à manger et à boire', 'Un ange le touche et dit : « Lève-toi, mange, car le chemin est trop long pour toi » (1 Rois 19.5-7). Dieu prend soin du corps de son serviteur.')$c398$;
  execute $c399$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 18, 'Vrai', 'Vrai : « Veille sur toi-même et sur ton enseignement ; persévère dans ces choses » (1 Timothée 4.16).')$c399$;
  execute $c400$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m1', 19, 'Parce qu’il était fidèle et qu’on ne trouvait chez lui ni faute ni rien de mauvais', 'Ils ne purent trouver « aucune occasion, ni aucune chose à reprendre, parce qu’il était fidèle » (Daniel 6.4). C’est une illustration vivante du mot « irréprochable ».')$c400$;
  execute $c401$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n4m2', 4, 20, 3)$c401$;
  execute $c402$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 0, 'Quatre', 'Paul (« de moi »), Timothée (« tu »), des hommes fidèles, et « d’autres » : quatre générations dans un seul verset (2 Timothée 2.2).')$c402$;
  execute $c403$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 1, 'À des hommes fidèles, capables de l’enseigner à d’autres', '« Confie-le à des hommes fidèles, qui soient capables de l’enseigner aussi à d’autres » (2 Timothée 2.2). La fidélité est le premier critère.')$c403$;
  execute $c404$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 2, 'Les avoir avec lui', '« Il en établit douze, pour les avoir avec lui, et pour les envoyer prêcher » (Marc 3.14). La relation précède l’envoi.')$c404$;
  execute $c405$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 3, 'Faites des disciples', 'Le verbe principal est mathêteusate, « faites des disciples » ; aller, baptiser et enseigner décrivent comment le faire.')$c405$;
  execute $c406$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 4, 'Il labourait avec des bœufs', 'Élie trouva Élisée « qui labourait », avec douze paires de bœufs devant lui (1 Rois 19.19).')$c406$;
  execute $c407$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 5, 'Comme celui qui versait l’eau sur les mains d’Élie', '« Il y a ici Élisée, fils de Schaphath, qui versait l’eau sur les mains d’Élie » (2 Rois 3.11). Il a été formé dans le service.')$c407$;
  execute $c408$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 6, 'Une double portion de son esprit', '« Qu’il y ait sur moi, je te prie, une double portion de ton esprit ! » (2 Rois 2.9).')$c408$;
  execute $c409$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 7, 'Faux', 'Faux : il a dit « Où est l’Éternel, le Dieu d’Élie ? » (2 Rois 2.14). La source de la puissance est Dieu, pas le mentor.')$c409$;
  execute $c410$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 8, 'Deux à deux', '« Il les envoya deux à deux devant lui dans toutes les villes et dans tous les lieux où lui-même devait aller » (Luc 10.1).')$c410$;
  execute $c411$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 9, 'De ce que leurs noms sont écrits dans les cieux', '« Ne vous réjouissez pas de ce que les esprits vous sont soumis ; mais réjouissez-vous de ce que vos noms sont écrits dans les cieux » (Luc 10.20).')$c411$;
  execute $c412$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 10, 'Ils racontèrent ce qu’ils avaient fait, et Jésus les prit à l’écart avec lui', '« Les apôtres, étant de retour, racontèrent à Jésus tout ce qu’ils avaient fait. Il les prit avec lui, et se retira à l’écart » (Luc 9.10). C’est un temps de débriefing.')$c412$;
  execute $c413$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 11, 'Leur incrédulité', '« C’est à cause de votre incrédulité, leur dit Jésus » (Matthieu 17.20). Il ajoute que cette sorte de démon ne sort que par la prière (et le jeûne).')$c413$;
  execute $c414$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 12, 'En particulier, quand ils l’ont interrogé', '« Alors les disciples s’approchèrent de Jésus, et lui dirent en particulier : Pourquoi n’avons-nous pu chasser ce démon ? » (Matthieu 17.19). La correction a eu lieu en privé.')$c414$;
  execute $c415$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 13, 'Tu fais, je t’aide', 'Les quatre étapes : je fais, tu regardes ; je fais, tu m’aides ; tu fais, je t’aide ; tu fais, je regarde.')$c415$;
  execute $c416$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 14, 'Tu t’épuiseras toi-même, et tu épuiseras ce peuple', '« Ce que tu fais n’est pas bien. Tu t’épuiseras toi-même, et tu épuiseras ce peuple qui est avec toi » (Exode 18.17-18).')$c416$;
  execute $c417$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 15, 'Capables, craignant Dieu, intègres, ennemis de la cupidité', '« Choisis parmi tout le peuple des hommes capables, craignant Dieu, des hommes intègres, ennemis de la cupidité » (Exode 18.21).')$c417$;
  execute $c418$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 16, 'En lui imposant les mains devant le prêtre Éléazar et toute l’assemblée', 'Moïse plaça Josué devant Éléazar et toute l’assemblée, posa les mains sur lui et lui donna ses ordres (Nombres 27.22-23).')$c418$;
  execute $c419$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 17, 'Fils d’exhortation', '« Joseph, surnommé par les apôtres Barnabas, ce qui signifie fils d’exhortation » (Actes 4.36).')$c419$;
  execute $c420$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 18, 'Vrai', 'Vrai : « Prends Marc, et amène-le avec toi, car il m’est utile pour le ministère » (2 Timothée 4.11). Celui qui avait échoué a été restauré.')$c420$;
  execute $c421$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m2', 19, 'Former dès maintenant des personnes fidèles et leur confier progressivement de vraies responsabilités', 'Comme Moïse avec Josué et Paul avec Timothée (2 Timothée 2.2), le leader forme des personnes fidèles et leur confie une responsabilité réelle avec accompagnement.')$c421$;
  execute $c422$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n4m3', 4, 21, 3)$c422$;
  execute $c423$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 0, 'La parole', '« Prêche la parole, insiste en toute occasion, favorable ou non » (2 Timothée 4.2).')$c423$;
  execute $c424$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 1, 'Proclamer publiquement comme un héraut', 'Kêrussô vient de kêrux, le héraut qui annonçait fidèlement le message officiel de son roi.')$c424$;
  execute $c425$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 2, 'Ils se donneront une foule de docteurs selon leurs propres désirs', '« Ayant la démangeaison d’entendre des choses agréables, ils se donneront une foule de docteurs selon leurs propres désirs » (2 Timothée 4.3).')$c425$;
  execute $c426$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 3, 'Sur la puissance de Dieu', 'Sa prédication reposait sur « une démonstration d’Esprit et de puissance, afin que votre foi fût fondée, non sur la sagesse des hommes, mais sur la puissance de Dieu ».')$c426$;
  execute $c427$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 4, 'Jésus-Christ, et Jésus-Christ crucifié', '« Je n’ai pas eu la pensée de savoir parmi vous autre chose que Jésus-Christ, et Jésus-Christ crucifié » (1 Corinthiens 2.2).')$c427$;
  execute $c428$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 5, 'Vrai', 'Vrai : « qu’il n’y ait pas parmi vous un grand nombre de personnes qui se mettent à enseigner, car vous savez que nous serons jugés plus sévèrement » (Jacques 3.1).')$c428$;
  execute $c429$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 6, 'Je ne sais point parler, car je suis un enfant', '« Ah ! Seigneur Éternel ! voici, je ne sais point parler, car je suis un enfant » (Jérémie 1.6).')$c429$;
  execute $c430$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 7, 'Il toucha sa bouche et mit ses paroles dans sa bouche', '« L’Éternel étendit sa main, et toucha ma bouche ; et l’Éternel me dit : Voici, je mets mes paroles dans ta bouche » (Jérémie 1.9).')$c430$;
  execute $c431$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 8, 'Comme un feu dévorant renfermé dans ses os', '« Il y a dans mon coeur comme un feu dévorant Qui est renfermé dans mes os. Je m’efforce de le contenir, et je ne le puis » (Jérémie 20.9).')$c431$;
  execute $c432$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 9, 'Étudier, mettre en pratique, enseigner', '« Esdras avait appliqué son coeur à étudier et à mettre en pratique la loi de l’Éternel, et à enseigner » (Esdras 7.10).')$c432$;
  execute $c433$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 10, 'Ils en donnaient le sens pour faire comprendre', '« Ils lisaient distinctement dans le livre de la loi de Dieu, et ils en donnaient le sens pour faire comprendre ce qu’ils avaient lu » (Néhémie 8.8).')$c433$;
  execute $c434$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 11, 'Parce qu’ils avaient compris les paroles qu’on leur avait expliquées', '« Car ils avaient compris les paroles qu’on leur avait expliquées » (Néhémie 8.12).')$c434$;
  execute $c435$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 12, 'La joie de l’Éternel', '« Ne vous affligez pas, car la joie de l’Éternel sera votre force » (Néhémie 8.10).')$c435$;
  execute $c436$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 13, 'Hommes frères, que ferons-nous ?', '« Ils eurent le coeur vivement touché, et ils dirent à Pierre et aux autres apôtres : Hommes frères, que ferons-nous ? » (Actes 2.37).')$c436$;
  execute $c437$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 14, 'Partir du texte biblique, l’étudier dans son contexte et en dégager l’idée centrale', 'Le prédicateur doit dispenser « droitement la parole de la vérité » (2 Timothée 2.15) et, comme les Lévites, donner le sens du texte (Néhémie 8.8).')$c437$;
  execute $c438$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 15, 'À un homme prudent qui a bâti sa maison sur le roc', '« Quiconque entend ces paroles que je dis et les met en pratique, sera semblable à un homme prudent qui a bâti sa maison sur le roc » (Matthieu 7.24).')$c438$;
  execute $c439$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 16, 'Il enseignait comme ayant autorité', '« Il enseignait comme ayant autorité, et non pas comme leurs scribes » (Matthieu 7.29).')$c439$;
  execute $c440$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 17, 'Selon que ses auditeurs étaient capables de l’entendre', '« Il leur annonçait la parole, selon qu’ils étaient capables de l’entendre » ; en particulier, il expliquait tout à ses disciples (Marc 4.33-34).')$c440$;
  execute $c441$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 18, 'Présenter à Dieu tout homme devenu parfait en Christ', '« Afin de présenter à Dieu tout homme, devenu parfait en Christ » (Colossiens 1.28) ; « parfait » (teleios) signifie mûr, accompli.')$c441$;
  execute $c442$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m3', 19, 'Faux', 'Faux : Jésus demanda d’abord « De quoi vous entretenez-vous en marchant ? » puis « Quoi ? », et les écouta avant de leur expliquer les Écritures (Luc 24.17-27).')$c442$;
  execute $c443$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n4m4', 4, 22, 3)$c443$;
  execute $c444$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 0, 'L’écrire et la graver sur des tables afin qu’on la lise couramment', 'Habacuc 2.2 : Écris la prophétie : grave-la sur des tables, afin qu’on la lise couramment.')$c444$;
  execute $c445$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 1, 'Il a pleuré, jeûné et prié pendant des jours', 'Néhémie 1.4 : il s’assit, pleura, fut plusieurs jours dans la désolation, jeûna et pria le Dieu des cieux.')$c445$;
  execute $c446$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 2, 'Pour évaluer la réalité avant de partager la vision', 'Néhémie 2.12-16 : il observe discrètement l’état des murs avant de présenter le projet ; observer précède partager.')$c446$;
  execute $c447$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 3, 'Levons-nous, et bâtissons !', 'Néhémie 2.18 : Ils dirent : Levons-nous, et bâtissons ! Et ils se fortifièrent dans cette bonne résolution.')$c447$;
  execute $c448$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 4, 'La parole révélée de Dieu', 'Châzôn désigne ce que Dieu fait voir à son prophète ; le parallèle avec la loi montre qu’il s’agit de la Parole de Dieu.')$c448$;
  execute $c449$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 5, 'Il s’assied pour calculer la dépense', 'Luc 14.28 : il s’assied d’abord pour calculer la dépense et voir s’il a de quoi la terminer.')$c449$;
  execute $c450$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 6, 'Faux', 'Jésus prend le calcul de la dépense comme exemple de sagesse (Luc 14.28) ; on planifie avec humilité en disant si Dieu le veut (Jacques 4.15).')$c450$;
  execute $c451$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 7, 'Il a prié et établi une garde jour et nuit', 'Néhémie 4.9 : Nous priâmes notre Dieu, et nous établîmes une garde jour et nuit ; prière et organisation vont ensemble.')$c451$;
  execute $c452$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 8, 'La circoncision des païens convertis pour être sauvés', 'Actes 15.1 : certains enseignaient : Si vous n’êtes circoncis selon le rite de Moïse, vous ne pouvez être sauvés.')$c452$;
  execute $c453$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 9, 'Amos', 'Actes 15.16-17 reprend Amos 9.11-12 : Dieu rebâtira la tente de David afin que les nations cherchent le Seigneur.')$c453$;
  execute $c454$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 10, 'Il a paru bon au Saint-Esprit et à nous', 'Actes 15.28 : Car il a paru bon au Saint-Esprit et à nous de ne pas vous imposer d’autre charge que ce qui est nécessaire.')$c454$;
  execute $c455$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 11, 'Aller le reprendre entre toi et lui seul', 'Matthieu 18.15 : va et reprends-le entre toi et lui seul. S’il t’écoute, tu as gagné ton frère.')$c455$;
  execute $c456$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 12, 'Gagner son frère', 'Le verbe kerdainô, gagner, montre que le but est la restauration de la relation (Matthieu 18.15).')$c456$;
  execute $c457$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 13, 'Il les exhorte toutes deux et demande à un collègue fidèle de les aider', 'Paul exhorte chacune à être d’un même sentiment dans le Seigneur et demande à un fidèle collègue de les aider (Philippiens 4.2-3).')$c457$;
  execute $c458$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 14, 'Protéger l’enfant et respecter la loi, y compris en signalant aux autorités', 'Les abus exigent de protéger la victime et de respecter la loi ; Romains 13 reconnaît le rôle des autorités et Matthieu 18.6 montre la gravité de scandaliser un petit.')$c458$;
  execute $c459$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 15, 'Tu t’épuiseras toi-même, et tu épuiseras ce peuple', 'Exode 18.18 : Tu t’épuiseras toi-même, et tu épuiseras ce peuple ; la chose est au-dessus de tes forces.')$c459$;
  execute $c460$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 16, 'Riches et influents', 'Exode 18.21 demande des hommes capables, craignant Dieu, intègres, ennemis de la cupidité ; la richesse n’est pas un critère.')$c460$;
  execute $c461$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 17, 'Pour que personne ne puisse le blâmer et pour agir bien devant Dieu et devant les hommes', '2 Corinthiens 8.20-21 : afin que personne ne nous blâme… car nous recherchons ce qui est bien, non seulement devant le Seigneur, mais aussi devant les hommes.')$c461$;
  execute $c462$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 18, 'La Parole de Dieu se répandait de plus en plus', 'Actes 6.7 : La parole de Dieu se répandait de plus en plus, et le nombre des disciples augmentait beaucoup à Jérusalem.')$c462$;
  execute $c463$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m4', 19, 'Faire compter l’argent par au moins deux personnes, le noter et le déposer sur un compte de l’église', 'Comme Paul en 2 Corinthiens 8, la gestion à plusieurs et la trace écrite protègent tout le monde et honorent Dieu (1 Corinthiens 14.40 ; Luc 16.10).')$c463$;
  execute $c464$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n4m5', 4, 23, 3)$c464$;
  execute $c465$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 0, 'En étant transformé par le renouvellement de l’intelligence', 'Romains 12.2 : soyez transformés par le renouvellement de l’intelligence, afin que vous discerniez quelle est la volonté de Dieu.')$c465$;
  execute $c466$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 1, 'Éprouver, tester puis approuver ce qui est authentique', 'Dokimazô évoque le test d’un métal précieux : on éprouve, puis on approuve ce qui a résisté à l’épreuve.')$c466$;
  execute $c467$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 2, 'Il est exercé par l’usage, comme par un entraînement', 'Hébreux 5.14 : ceux dont le jugement est exercé par l’usage ; le verbe gumnazô évoque l’entraînement de l’athlète.')$c467$;
  execute $c468$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 3, 'Tout n’est pas utile, et tout n’édifie pas', '1 Corinthiens 10.23 : Tout est permis, mais tout n’est pas utile ; tout est permis, mais tout n’édifie pas.')$c468$;
  execute $c469$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 4, 'Faire tout pour la gloire de Dieu', '1 Corinthiens 10.31 : soit que vous mangiez, soit que vous buviez, soit que vous fassiez quelque autre chose, faites tout pour la gloire de Dieu.')$c469$;
  execute $c470$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 5, 'De se souiller par les mets et le vin du roi', 'Daniel 1.8 : Daniel résolut de ne pas se souiller par les mets du roi et par le vin dont le roi buvait.')$c470$;
  execute $c471$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 6, 'Un essai de dix jours avec des légumes et de l’eau', 'Daniel 1.12 : Éprouve tes serviteurs pendant dix jours, et qu’on nous donne des légumes à manger et de l’eau à boire.')$c471$;
  execute $c472$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 7, 'Chacun doit être pleinement persuadé dans son esprit, sans juger les autres', 'Romains 14.5 : que chacun ait en son esprit une pleine conviction ; et Romains 14.1 demande de ne pas discuter des opinions.')$c472$;
  execute $c473$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 8, 'Parce que Dieu a fait l’homme à son image', 'Genèse 9.6 : Si quelqu’un verse le sang de l’homme, par l’homme son sang sera versé ; car Dieu a fait l’homme à son image.')$c473$;
  execute $c474$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 9, 'Que Dieu forme la personne dans le sein de sa mère et la voit déjà', 'Psaume 139.13,16 : tu m’as tissé dans le sein de ma mère ; quand je n’étais qu’une masse informe, tes yeux me voyaient.')$c474$;
  execute $c475$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 10, 'Parce qu’elles craignaient Dieu', 'Exode 1.17 : les sages-femmes craignirent Dieu, et ne firent point ce que leur avait dit le roi d’Égypte ; elles laissèrent vivre les enfants.')$c475$;
  execute $c476$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 11, 'Au récit de la création dans la Genèse', 'Matthieu 19.4-5 : N’avez-vous pas lu que le créateur, au commencement, fit l’homme et la femme… ? Jésus cite Genèse 1.27 et 2.24.')$c476$;
  execute $c477$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 12, 'Je ne te condamne pas non plus : va, et ne pèche plus', 'Jean 8.11 : Je ne te condamne pas non plus : va, et ne pèche plus. Jésus unit la grâce et la vérité.')$c477$;
  execute $c478$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 13, 'Faux', 'Toute personne est créée à l’image de Dieu (Genèse 1.27) ; Jésus, plein de grâce et de vérité, accueille sans mépris tout en appelant à la sainteté.')$c478$;
  execute $c479$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 14, 'L’entourer, l’écouter et l’aider concrètement à accueillir son enfant', 'Une Église qui défend la vie (Psaume 139) doit aussi accompagner concrètement les mères en détresse, avec la compassion de Jésus.')$c479$;
  execute $c480$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 15, 'Ce qui est vrai, honorable, juste, pur et aimable', 'Philippiens 4.8 : que tout ce qui est vrai, honorable, juste, pur, aimable… soit l’objet de vos pensées.')$c480$;
  execute $c481$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 16, 'Saisir les occasions favorables de faire le bien', 'Exagorazô signifie racheter, saisir ; kairos désigne le moment favorable. Il faut saisir chaque occasion de faire le bien.')$c481$;
  execute $c482$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 17, 'L’amour de l’argent', '1 Timothée 6.10 : l’amour de l’argent est une racine de tous les maux ; ce n’est pas l’argent lui-même.')$c482$;
  execute $c483$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 18, 'Il a refusé, pour montrer que la grâce de Dieu ne s’achète pas', '2 Rois 5.16 : L’Éternel, dont je suis le serviteur, est vivant ! je n’accepterai pas.')$c483$;
  execute $c484$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m5', 19, 'La lèpre de Naaman s’attacha à lui', '2 Rois 5.27 : la lèpre de Naaman s’attacha à Guéhazi, qui sortit de devant Élisée blanc de lèpre comme la neige.')$c484$;
  execute $c485$insert into public.modules (id, niveau, ordre, nb_lecons) values ('n4m6', 4, 24, 3)$c485$;
  execute $c486$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 0, 'Une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas', 'Hébreux 11.1 : Or la foi est une ferme assurance des choses qu’on espère, une démonstration de celles qu’on ne voit pas.')$c486$;
  execute $c487$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 1, 'C’est par la foi', 'Le mot pistei, c’est par la foi, rythme tout le chapitre : par la foi Abel, Noé, Abraham, Moïse, Rahab…')$c487$;
  execute $c488$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 2, 'Que Dieu existe et qu’il est le rémunérateur de ceux qui le cherchent', 'Hébreux 11.6 : il faut que celui qui s’approche de Dieu croie que Dieu existe, et qu’il est le rémunérateur de ceux qui le cherchent.')$c488$;
  execute $c489$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 3, 'Faux', 'Abraham a menti, Moïse a tué un Égyptien, Rahab était une prostituée, Gédéon doutait : ils ont été retenus pour leur foi, non pour leur perfection.')$c489$;
  execute $c490$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 4, 'Sur Jésus, le chef et le consommateur de la foi', 'Hébreux 12.2 : ayant les regards sur Jésus, le chef et le consommateur de la foi.')$c490$;
  execute $c491$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 5, 'Il battait du blé dans le pressoir pour le cacher', 'Juges 6.11-12 : Gédéon battait du froment au pressoir pour le mettre à l’abri de Madian ; l’ange lui dit : L’Éternel est avec toi, vaillant héros !')$c491$;
  execute $c492$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 6, 'Pour qu’Israël ne se glorifie pas en disant que sa propre main l’avait délivré', 'Juges 7.2 : Le peuple que tu as avec toi est trop nombreux… il pourrait en tirer gloire contre moi, et dire : C’est ma main qui m’a délivré.')$c492$;
  execute $c493$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 7, 'Que toutes les familles de la terre soient bénies en lui', 'Genèse 12.3 : et toutes les familles de la terre seront bénies en toi.')$c493$;
  execute $c494$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 8, 'Il savait que Dieu est compatissant et pourrait faire grâce à Ninive', 'Jonas 4.2 : je savais que tu es un Dieu compatissant et miséricordieux, lent à la colère et riche en bonté, et qui te repens du mal.')$c494$;
  execute $c495$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 9, 'Ils ont cru à Dieu, jeûné et se sont détournés de leur mauvaise voie', 'Jonas 3.5-10 : les gens de Ninive crurent à Dieu, publièrent un jeûne, se revêtirent de sacs, et Dieu vit qu’ils revenaient de leur mauvaise voie.')$c495$;
  execute $c496$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 10, 'Par une question de Dieu sur sa compassion pour Ninive', 'Jonas 4.11 : Et moi, je n’aurais pas pitié de Ninive, la grande ville… ? Le livre se termine sur cette question.')$c496$;
  execute $c497$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 11, 'Barnabas et Saul', 'Actes 13.2 : Mettez-moi à part Barnabas et Saul pour l’œuvre à laquelle je les ai appelés.')$c497$;
  execute $c498$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 12, 'Elle servait le Seigneur et jeûnait', 'Actes 13.2 : Pendant qu’ils servaient le Seigneur dans leur ministère et qu’ils jeûnaient, le Saint-Esprit dit…')$c498$;
  execute $c499$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 13, 'De toute nation, de toute tribu, de tout peuple et de toute langue', 'Apocalypse 7.9 : une grande foule, que personne ne pouvait compter, de toute nation, de toute tribu, de tout peuple, et de toute langue.')$c499$;
  execute $c500$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 14, 'Parce que les gens ne peuvent croire en celui dont ils n’ont pas entendu parler', 'Romains 10.14 : Comment croiront-ils en celui dont ils n’ont pas entendu parler ? Et comment en entendront-ils parler, s’il n’y a personne qui prêche ?')$c500$;
  execute $c501$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 15, 'J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi', '2 Timothée 4.7 : J’ai combattu le bon combat, j’ai achevé la course, j’ai gardé la foi.')$c501$;
  execute $c502$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 16, 'Pour annoncer la puissance de Dieu à la génération future', 'Psaume 71.18 : afin que j’annonce ta force à la génération présente, ta puissance à la génération future.')$c502$;
  execute $c503$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 17, 'La montagne d’Hébron, où habitaient les fils d’Anak', 'Josué 14.12 : Donne-moi donc cette montagne dont l’Éternel a parlé dans ce temps-là ; car tu as appris alors qu’il s’y trouve des Anakim.')$c503$;
  execute $c504$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 18, 'Parce qu’il avait pleinement suivi la voie de l’Éternel', 'Josué 14.14 : C’est ainsi que Caleb… a eu jusqu’à ce jour Hébron pour héritage, parce qu’il avait pleinement suivi la voie de l’Éternel, le Dieu d’Israël.')$c504$;
  execute $c505$insert into public.cles_examen (module_id, question, reponse, explication) values ('n4m6', 19, '2 Timothée 2.2 : confie-le à des hommes fidèles, capables de l’enseigner aussi à d’autres', '2 Timothée 2.2 décrit une chaîne de transmission : Paul, Timothée, des hommes fidèles, et d’autres encore.')$c505$;
